    final ChunkInputStream stream = throwingChunkInputStream(ex, len, true);
    when(this.refreshFunction.apply(any())).thenAnswer(inv -> refreshPipelineFunction.apply(blockID));
    try (BlockInputStream subject = createSubject(blockID, blockLocationInfo.getPipeline(), stream)) {
        subject.initialize();
        // WHEN
        byte[] b = new byte[len];
