@ContainerLayoutTestInfo.ContainerTest
public void testContainerCloseActionWhenVolumeFull(ContainerLayoutVersion layoutVersion) throws Exception {
    String testDirPath = testDir.getPath();
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setStorageSize(DatanodeConfiguration.HDDS_DATANODE_VOLUME_MIN_FREE_SPACE, 100.0, StorageUnit.BYTES);
    DatanodeDetails dd = randomDatanodeDetails();
    HddsVolume.Builder volumeBuilder = new HddsVolume.Builder(testDirPath).datanodeUuid(dd.getUuidString()).conf(conf).usageCheckFactory(MockSpaceUsageCheckFactory.NONE).clusterID("test");
    // state of cluster : available (160) > 100  ,datanode volume
    // utilisation threshold not yet reached. container creates are successful.
    AtomicLong usedSpace = new AtomicLong(340);
    SpaceUsageSource spaceUsage = MockSpaceUsageSource.of(500, usedSpace);
    SpaceUsageCheckFactory factory = MockSpaceUsageCheckFactory.of(spaceUsage, Duration.ZERO, inMemory(new AtomicLong(0)));
    volumeBuilder.usageCheckFactory(factory);
    MutableVolumeSet volumeSet = mock(MutableVolumeSet.class);
    when(volumeSet.getVolumesList()).thenReturn(Collections.singletonList(volumeBuilder.build()));
    volumeSet.getVolumesList().get(0).setState(StorageVolume.VolumeState.NORMAL);
    volumeSet.getVolumesList().get(0).start();
    try {
        UUID scmId = UUID.randomUUID();
        ContainerSet containerSet = newContainerSet();
        StateContext context = ContainerTestUtils.getMockContext(dd, conf);
        DatanodeStateMachine stateMachine = context.getParent();
        // create a 50 byte container
        // available (160) > 100 (min free space) + 50 (container size)
        KeyValueContainerData containerData = new KeyValueContainerData(1L, layoutVersion, 50, UUID.randomUUID().toString(), dd.getUuidString());
        Container container = new KeyValueContainer(containerData, conf);
        StorageVolumeUtil.getHddsVolumesList(volumeSet.getVolumesList()).forEach(hddsVolume -> hddsVolume.setDbParentDir(tempDir.toFile()));
        container.create(volumeSet, new RoundRobinVolumeChoosingPolicy(), scmId.toString());
        containerSet.addContainer(container);
        ContainerMetrics metrics = ContainerMetrics.create(conf);
        Map<ContainerType, Handler> handlers = Maps.newHashMap();
        for (ContainerType containerType : ContainerType.values()) {
            handlers.put(containerType, Handler.getHandlerForContainerType(containerType, conf, context.getParent().getDatanodeDetails().getUuidString(), containerSet, volumeSet, volumeChoosingPolicy, metrics, NO_OP_ICR_SENDER, new ContainerChecksumTreeManager(conf)));
        }
        HddsDispatcher hddsDispatcher = new HddsDispatcher(conf, containerSet, volumeSet, handlers, context, metrics, null);
        hddsDispatcher.setClusterId(scmId.toString());
        containerData.getVolume().getVolumeUsage().ifPresent(usage -> usage.incrementUsedSpace(60));
        usedSpace.addAndGet(60);
        ContainerCommandResponseProto response = hddsDispatcher.dispatch(getWriteChunkRequest(dd.getUuidString(), 1L, 1L), null);
        assertEquals(ContainerProtos.Result.DISK_OUT_OF_SPACE, response.getResult());
        verify(context, times(1)).addContainerActionIfAbsent(any(ContainerAction.class));
        // verify that immediate heartbeat is triggered
        verify(stateMachine, times(1)).triggerHeartbeat();
        // the volume has reached the min free space boundary but this time the heartbeat should not be triggered because
        // of throttling
        hddsDispatcher.dispatch(getWriteChunkRequest(dd.getUuidString(), 1L, 2L), null);
        verify(context, times(2)).addContainerActionIfAbsent(any(ContainerAction.class));
        // was called once before
        verify(stateMachine, times(1)).triggerHeartbeat();
        // try creating another container now as the volume used has crossed
        // threshold
        KeyValueContainerData containerData2 = new KeyValueContainerData(1L, layoutVersion, 50, UUID.randomUUID().toString(), dd.getUuidString());
        Container container2 = new KeyValueContainer(containerData2, conf);
        StorageContainerException scException = assertThrows(StorageContainerException.class, () -> container2.create(volumeSet, new RoundRobinVolumeChoosingPolicy(), scmId.toString()));
        assertEquals("Container creation failed, due to disk out of space", scException.getMessage());
    } finally {
        volumeSet.shutdown();
        ContainerMetrics.remove();
    }
}

