@Test
public void testMetrics() {
    ReconstructECContainersCommandHandler commandHandler = new ReconstructECContainersCommandHandler(conf, supervisor, coordinator);
    doNothing().when(supervisor).addTask(any());
    Map<SCMCommandProto.Type, CommandHandler> handlerMap = new HashMap<>();
    handlerMap.put(commandHandler.getCommandType(), commandHandler);
    CommandHandlerMetrics metrics = CommandHandlerMetrics.create(handlerMap);
    try {
        byte[] missingIndexes = { 1, 2 };
        ByteString missingContainerIndexes = Proto2Utils.unsafeByteString(missingIndexes);
        ECReplicationConfig ecReplicationConfig = new ECReplicationConfig(3, 2);
        List<DatanodeDetails> dnDetails = getDNDetails(5);
        List<ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex> sources = dnDetails.stream().map(a -> new ReconstructECContainersCommand.DatanodeDetailsAndReplicaIndex(a, dnDetails.indexOf(a))).collect(Collectors.toList());
        List<DatanodeDetails> targets = getDNDetails(2);
        ReconstructECContainersCommand reconstructECContainersCommand = new ReconstructECContainersCommand(1L, sources, targets, missingContainerIndexes, ecReplicationConfig);
        commandHandler.handle(reconstructECContainersCommand, ozoneContainer, stateContext, connectionManager);
        String metricsName = "ECReconstructions";
        assertEquals(commandHandler.getMetricsName(), metricsName);
        when(supervisor.getReplicationRequestCount(metricsName)).thenReturn(1L);
        assertEquals(commandHandler.getInvocationCount(), 1);
        commandHandler.handle(new ReconstructECContainersCommand(2L, sources, targets, missingContainerIndexes, ecReplicationConfig), ozoneContainer, stateContext, connectionManager);
        commandHandler.handle(new ReconstructECContainersCommand(3L, sources, targets, missingContainerIndexes, ecReplicationConfig), ozoneContainer, stateContext, connectionManager);
        commandHandler.handle(new ReconstructECContainersCommand(4L, sources, targets, missingContainerIndexes, ecReplicationConfig), ozoneContainer, stateContext, connectionManager);
        commandHandler.handle(new ReconstructECContainersCommand(5L, sources, targets, missingContainerIndexes, ecReplicationConfig), ozoneContainer, stateContext, connectionManager);
        commandHandler.handle(new ReconstructECContainersCommand(6L, sources, targets, missingContainerIndexes, ecReplicationConfig), ozoneContainer, stateContext, connectionManager);
        when(supervisor.getReplicationRequestCount(metricsName)).thenReturn(5L);
        when(supervisor.getReplicationRequestTotalTime(metricsName)).thenReturn(10L);
        when(supervisor.getReplicationRequestAvgTime(metricsName)).thenReturn(2L);
        when(supervisor.getReplicationQueuedCount(metricsName)).thenReturn(1L);
        assertEquals(commandHandler.getInvocationCount(), 5);
        assertEquals(commandHandler.getQueuedCount(), 1);
        assertEquals(commandHandler.getTotalRunTime(), 10);
        assertEquals(commandHandler.getAverageRunTime(), 2);
        MetricsCollectorImpl metricsCollector = new MetricsCollectorImpl();
        metrics.getMetrics(metricsCollector, true);
        assertEquals(1, metricsCollector.getRecords().size());
    } finally {
        metrics.unRegister();
    }
}

