private void init(ContainerTestVersionInfo versionInfo) throws Exception {
    setVersionInfo(versionInfo);
    CodecBuffer.enableLeakDetection();
    DatanodeConfiguration dc = CONF.getObject(DatanodeConfiguration.class);
    dc.setAutoCompactionSmallSstFile(true);
    dc.setAutoCompactionSmallSstFileNum(100);
    dc.setRocksdbDeleteObsoleteFilesPeriod(5000);
    CONF.setFromObject(dc);
    datanodeId = UUID.randomUUID();
    hddsVolumes = new ArrayList<>();
    hddsVolumes.add(new HddsVolume.Builder(folder.toString()).conf(CONF).datanodeUuid(datanodeId.toString()).build());
    StorageVolumeUtil.checkVolume(hddsVolumes.get(0), scmId, scmId, CONF, null, null);
    volumeSet = mock(MutableVolumeSet.class);
    volumeChoosingPolicy = mock(RoundRobinVolumeChoosingPolicy.class);
    when(volumeSet.getVolumesList()).thenAnswer(i -> hddsVolumes.stream().map(v -> (StorageVolume) v).collect(Collectors.toList()));
    when(volumeChoosingPolicy.chooseVolume(anyList(), anyLong())).thenAnswer(invocation -> {
        List<HddsVolume> volumes = invocation.getArgument(0);
        return volumes.get(0);
    });
    keyValueContainerData = new KeyValueContainerData(1L, layout, (long) StorageUnit.GB.toBytes(5), UUID.randomUUID().toString(), datanodeId.toString());
    keyValueContainer = new KeyValueContainer(keyValueContainerData, CONF);
}

