@ContainerTestVersionInfo.ContainerTest
public void testDuplicateContainer(ContainerTestVersionInfo versionInfo) throws Exception {
    init(versionInfo);
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    StorageContainerException exception = assertThrows(StorageContainerException.class, () -> keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId));
    assertEquals(ContainerProtos.Result.CONTAINER_ALREADY_EXISTS, exception.getResult());
    assertThat(exception).hasMessage("Container creation failed because ContainerFile already exists");
}

@ContainerTestVersionInfo.ContainerTest
public void testDeleteContainer(ContainerTestVersionInfo versionInfo) throws Exception {
    init(versionInfo);
    closeContainer();
    keyValueContainer = new KeyValueContainer(keyValueContainerData, CONF);
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    KeyValueContainerUtil.removeContainer(keyValueContainer.getContainerData(), CONF);
    keyValueContainer.delete();
    String containerMetaDataPath = keyValueContainerData.getMetadataPath();
    File containerMetaDataLoc = new File(containerMetaDataPath);
    assertFalse(containerMetaDataLoc.getParentFile().exists(), "Container directory still exists");
    assertFalse(keyValueContainer.getContainerFile().exists(), "Container File still exists");
    if (isSameSchemaVersion(schemaVersion, OzoneConsts.SCHEMA_V3)) {
        assertTrue(keyValueContainer.getContainerDBFile().exists());
    } else {
        assertFalse(keyValueContainer.getContainerDBFile().exists(), "Container DB file still exists");
    }
}

@ContainerTestVersionInfo.ContainerTest
public void testCloseContainer(ContainerTestVersionInfo versionInfo) throws Exception {
    init(versionInfo);
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    keyValueContainer.close();
    keyValueContainerData = keyValueContainer.getContainerData();
    assertEquals(ContainerProtos.ContainerDataProto.State.CLOSED, keyValueContainerData.getState());
    //Check state in the .container file
    File containerFile = keyValueContainer.getContainerFile();
    keyValueContainerData = (KeyValueContainerData) ContainerDataYaml.readContainerFile(containerFile);
    assertEquals(ContainerProtos.ContainerDataProto.State.CLOSED, keyValueContainerData.getState());
}

@ContainerTestVersionInfo.ContainerTest
public void testReportOfUnhealthyContainer(ContainerTestVersionInfo versionInfo) throws Exception {
