@ContainerTestVersionInfo.ContainerTest
public void testContainerImportExport(ContainerTestVersionInfo versionInfo) throws Exception {
    init(versionInfo);
    long containerId = keyValueContainer.getContainerData().getContainerID();
    createContainer();
    long numberOfKeysToWrite = 12;
    closeContainer();
    populate(numberOfKeysToWrite);
    // Create merkle tree and set data checksum to simulate actual key value container.
    File checksumFile = ContainerChecksumTreeManager.getContainerChecksumFile(keyValueContainer.getContainerData());
    ContainerProtos.ContainerMerkleTree containerMerkleTreeWriterProto = buildTestTree(CONF).toProto();
    keyValueContainerData.setDataChecksum(containerMerkleTreeWriterProto.getDataChecksum());
    ContainerProtos.ContainerChecksumInfo containerInfo = ContainerProtos.ContainerChecksumInfo.newBuilder().setContainerID(containerId).setContainerMerkleTree(containerMerkleTreeWriterProto).build();
    try (OutputStream tmpOutputStream = Files.newOutputStream(checksumFile.toPath())) {
        containerInfo.writeTo(tmpOutputStream);
    }
    //destination path
    File folderToExport = Files.createFile(folder.toPath().resolve("export.tar")).toFile();
    for (CopyContainerCompression compr : CopyContainerCompression.values()) {
        TarContainerPacker packer = new TarContainerPacker(compr);
        //export the container
        try (OutputStream fos = Files.newOutputStream(folderToExport.toPath())) {
            keyValueContainer.exportContainerData(fos, packer);
        }
        //delete the original one
        KeyValueContainerUtil.removeContainer(keyValueContainer.getContainerData(), CONF);
        keyValueContainer.delete();
        //create a new one
        KeyValueContainerData containerData = new KeyValueContainerData(containerId, keyValueContainerData.getLayoutVersion(), keyValueContainerData.getMaxSize(), UUID.randomUUID().toString(), datanodeId.toString());
        containerData.setSchemaVersion(keyValueContainerData.getSchemaVersion());
        KeyValueContainer container = new KeyValueContainer(containerData, CONF);
        HddsVolume containerVolume = volumeChoosingPolicy.chooseVolume(StorageVolumeUtil.getHddsVolumesList(volumeSet.getVolumesList()), 1);
        container.populatePathFields(scmId, containerVolume);
        try (InputStream fis = Files.newInputStream(folderToExport.toPath())) {
            container.importContainerData(fis, packer);
        }
        assertEquals("value1", containerData.getMetadata().get("key1"));
        assertEquals(keyValueContainerData.getContainerDBType(), containerData.getContainerDBType());
        assertEquals(keyValueContainerData.getState(), containerData.getState());
        assertEquals(numberOfKeysToWrite, containerData.getBlockCount());
        assertEquals(keyValueContainerData.getLayoutVersion(), containerData.getLayoutVersion());
        assertEquals(keyValueContainerData.getMaxSize(), containerData.getMaxSize());
        assertEquals(keyValueContainerData.getBytesUsed(), containerData.getBytesUsed());
        assertEquals(keyValueContainerData.getDataChecksum(), containerData.getDataChecksum());
        verifyAllDataChecksumsMatch(containerData, CONF);
        assertNotNull(containerData.getContainerFileChecksum());
        assertNotEquals(containerData.ZERO_CHECKSUM, container.getContainerData().getContainerFileChecksum());
        //Can't overwrite existing container
        KeyValueContainer finalContainer = container;
        assertThrows(IOException.class, () -> {
            try (InputStream fis = Files.newInputStream(folderToExport.toPath())) {
                finalContainer.importContainerData(fis, packer);
            }
        }, "Container is imported twice. Previous files are overwritten");
        //all good
        assertTrue(container.getContainerFile().exists());
        //Import failure should cleanup the container directory
        containerData = new KeyValueContainerData(containerId + 1, keyValueContainerData.getLayoutVersion(), keyValueContainerData.getMaxSize(), UUID.randomUUID().toString(), datanodeId.toString());
        containerData.setSchemaVersion(keyValueContainerData.getSchemaVersion());
        container = new KeyValueContainer(containerData, CONF);
        containerVolume = volumeChoosingPolicy.chooseVolume(StorageVolumeUtil.getHddsVolumesList(volumeSet.getVolumesList()), 1);
        container.populatePathFields(scmId, containerVolume);
        KeyValueContainer finalContainer1 = container;
        assertThrows(IOException.class, () -> {
            try {
                InputStream fis = Files.newInputStream(folderToExport.toPath());
                fis.close();
                finalContainer1.importContainerData(fis, packer);
            } finally {
                File directory = new File(finalContainer1.getContainerData().getContainerPath());
                assertFalse(directory.exists());
            }
        });
    }
}

