    // Override the class, so that the first time we call it, it throws
    // simulating a disk or write failure. The second time it should be ok
    final AtomicInteger callCount = new AtomicInteger(0);
    keyValueContainer = new KeyValueContainer(keyValueContainerData, CONF) {

        @Override
        protected void createContainerMetaData(File containerMetaDataPath, File chunksPath, File dbFile, String schemaVers, ConfigurationSource configuration) throws IOException {
            if (callCount.get() == 0) {
                callCount.incrementAndGet();
                throw new IOException("Injected failure");
            } else {
                callCount.incrementAndGet();
                super.createContainerMetaData(containerMetaDataPath, chunksPath, dbFile, schemaVers, configuration);
            }
        }
    };
    testCreateContainer();
    // We should have called the mocked class twice. Once to get an error and
    // then retry without a failure.
    assertEquals(2, callCount.get());
}

