@ContainerTestVersionInfo.ContainerTest
public void testContainerRocksDB(ContainerTestVersionInfo versionInfo) throws Exception {
    init(versionInfo);
    closeContainer();
    keyValueContainer = new KeyValueContainer(keyValueContainerData, CONF);
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    try (DBHandle db = BlockUtils.getDB(keyValueContainerData, CONF)) {
        RDBStore store = (RDBStore) db.getStore().getStore();
        long defaultCacheSize = OzoneConsts.GB;
        long cacheSize = Long.parseLong(store.getProperty("rocksdb.block-cache-capacity"));
        assertEquals(defaultCacheSize, cacheSize);
        for (ColumnFamily handle : store.getColumnFamilies()) {
            cacheSize = Long.parseLong(store.getProperty(handle, "rocksdb.block-cache-capacity"));
            assertEquals(defaultCacheSize, cacheSize);
        }
    }
}

