@ContainerTestVersionInfo.ContainerTest
public void testMultipleContainerReader(ContainerTestVersionInfo versionInfo) throws Exception {
    setLayoutAndSchemaVersion(versionInfo);
    setup(versionInfo);
    final int volumeNum = 10;
    StringBuffer datanodeDirs = new StringBuffer();
    File[] volumeDirs = new File[volumeNum];
    for (int i = 0; i < volumeNum; i++) {
        volumeDirs[i] = Files.createDirectory(tempDir.resolve("volumeDir" + i)).toFile();
        datanodeDirs = datanodeDirs.append(volumeDirs[i]).append(',');
    }
    BlockUtils.shutdownCache(conf);
    conf.set(ScmConfigKeys.HDDS_DATANODE_DIR_KEY, datanodeDirs.toString());
    conf.set(OzoneConfigKeys.HDDS_CONTAINER_RATIS_DATANODE_STORAGE_DIR, datanodeDirs.toString());
    MutableVolumeSet volumeSets = new MutableVolumeSet(datanodeId.toString(), clusterId, conf, null, StorageVolume.VolumeType.DATA_VOLUME, null);
    for (StorageVolume v : volumeSets.getVolumesList()) {
        StorageVolumeUtil.checkVolume(v, clusterId, clusterId, conf, null, null);
    }
    createDbInstancesForTestIfNeeded(volumeSets, clusterId, clusterId, conf);
    ContainerCache cache = ContainerCache.getInstance(conf);
    cache.shutdownCache();
    RoundRobinVolumeChoosingPolicy policy = new RoundRobinVolumeChoosingPolicy();
    final int containerCount = 100;
    blockCount = containerCount;
    KeyValueContainer conflict01 = null;
    KeyValueContainer conflict02 = null;
    KeyValueContainer conflict11 = null;
    KeyValueContainer conflict12 = null;
    KeyValueContainer conflict21 = null;
    KeyValueContainer conflict22 = null;
    KeyValueContainer ec1 = null;
    KeyValueContainer ec2 = null;
    KeyValueContainer ec3 = null;
    KeyValueContainer ec4 = null;
    KeyValueContainer ec5 = null;
    KeyValueContainer ec6 = null;
    KeyValueContainer ec7 = null;
    long baseBCSID = 10L;
    for (int i = 0; i < containerCount; i++) {
        if (i == 0) {
            // Create a duplicate container with ID 0. Both have the same BSCID
            conflict01 = createContainerWithId(0, volumeSets, policy, baseBCSID, 0);
            conflict02 = createContainerWithId(0, volumeSets, policy, baseBCSID, 0);
        } else if (i == 1) {
            // Create a duplicate container with ID 1 so that the one has a
            // larger BCSID
            conflict11 = createContainerWithId(1, volumeSets, policy, baseBCSID, 0);
            conflict12 = createContainerWithId(1, volumeSets, policy, baseBCSID - 1, 0);
        } else if (i == 2) {
            conflict21 = createContainerWithId(i, volumeSets, policy, baseBCSID, 0);
            conflict22 = createContainerWithId(i, volumeSets, policy, baseBCSID, 0);
            conflict22.close();
        } else if (i == 3) {
            ec1 = createContainerWithId(i, volumeSets, policy, baseBCSID, 1);
            ec2 = createContainerWithId(i, volumeSets, policy, baseBCSID, 1);
        } else if (i == 4) {
            ec3 = createContainerWithId(i, volumeSets, policy, baseBCSID, 1);
            ec4 = createContainerWithId(i, volumeSets, policy, baseBCSID, 2);
            ec3.close();
            ec4.close();
            mockMetadataStore.getContainerCreateInfoTable().put(ContainerID.valueOf(i), ContainerCreateInfo.valueOf(ContainerProtos.ContainerDataProto.State.CLOSED, 1));
        } else if (i == 5) {
            ec5 = createContainerWithId(i, volumeSets, policy, baseBCSID, 1);
            ec6 = createContainerWithId(i, volumeSets, policy, baseBCSID, 2);
            ec6.close();
            ec5.close();
            mockMetadataStore.getContainerCreateInfoTable().put(ContainerID.valueOf(i), ContainerCreateInfo.valueOf(ContainerProtos.ContainerDataProto.State.CLOSED, 2));
        } else if (i == 6) {
            ec7 = createContainerWithId(i, volumeSets, policy, baseBCSID, 3);
            ec7.close();
            mockMetadataStore.getContainerCreateInfoTable().put(ContainerID.valueOf(i), ContainerCreateInfo.valueOf(ContainerProtos.ContainerDataProto.State.CLOSED, -1));
        } else {
            createContainerWithId(i, volumeSets, policy, baseBCSID, 0);
        }
    }
    // Close the RocksDB instance for this container and remove from the cache
    // so it does not affect the ContainerReader, which avoids using the cache
    // at startup for performance reasons.
    cache.shutdownCache();
    List<StorageVolume> volumes = volumeSets.getVolumesList();
    ContainerReader[] containerReaders = new ContainerReader[volumeNum];
    Thread[] threads = new Thread[volumeNum];
    for (int i = 0; i < volumeNum; i++) {
        containerReaders[i] = new ContainerReader(volumeSets, (HddsVolume) volumes.get(i), containerSet, conf, true);
        threads[i] = new Thread(containerReaders[i]);
    }
    long startTime = Time.monotonicNow();
    for (int i = 0; i < volumeNum; i++) {
        threads[i].start();
    }
    for (int i = 0; i < volumeNum; i++) {
        threads[i].join();
    }
    System.out.println("Open " + volumeNum + " Volume with " + containerCount + " costs " + (Time.monotonicNow() - startTime) / 1000 + "s");
    assertEquals(containerCount, containerSet.getContainerMap().entrySet().size());
    assertEquals(volumeSet.getFailedVolumesList().size(), 0);
    // One of the conflict01 or conflict02 should have had its container path
    // removed.
    List<Path> paths = new ArrayList<>();
    paths.add(Paths.get(conflict01.getContainerData().getContainerPath()));
    paths.add(Paths.get(conflict02.getContainerData().getContainerPath()));
    int exist = 0;
    for (Path p : paths) {
        if (Files.exists(p)) {
            exist++;
        }
    }
    assertEquals(1, exist);
    assertThat(paths).contains(Paths.get(containerSet.getContainer(0).getContainerData().getContainerPath()));
    // For conflict1, the one with the larger BCSID should win, which is
    // conflict11.
    assertFalse(Files.exists(Paths.get(conflict12.getContainerData().getContainerPath())));
    assertEquals(conflict11.getContainerData().getContainerPath(), containerSet.getContainer(1).getContainerData().getContainerPath());
    assertEquals(baseBCSID, containerSet.getContainer(1).getContainerData().getBlockCommitSequenceId());
    // For conflict2, the closed on (conflict22) should win.
    assertFalse(Files.exists(Paths.get(conflict21.getContainerData().getContainerPath())));
    assertEquals(conflict22.getContainerData().getContainerPath(), containerSet.getContainer(2).getContainerData().getContainerPath());
    assertEquals(ContainerProtos.ContainerDataProto.State.CLOSED, containerSet.getContainer(2).getContainerData().getState());
    // For the EC conflict, both containers should be left on disk
    assertTrue(Files.exists(Paths.get(ec1.getContainerData().getContainerPath())));
    assertTrue(Files.exists(Paths.get(ec2.getContainerData().getContainerPath())));
    assertNotNull(containerSet.getContainer(3));
    // For EC conflict with different replica index, all container present but containerSet loaded with same
    // replica index as the one in DB.
    assertTrue(Files.exists(Paths.get(ec3.getContainerData().getContainerPath())));
    assertTrue(Files.exists(Paths.get(ec4.getContainerData().getContainerPath())));
    assertEquals(containerSet.getContainer(ec3.getContainerData().getContainerID()).getContainerData().getReplicaIndex(), ec3.getContainerData().getReplicaIndex());
    assertTrue(Files.exists(Paths.get(ec5.getContainerData().getContainerPath())));
    assertTrue(Files.exists(Paths.get(ec6.getContainerData().getContainerPath())));
    assertEquals(containerSet.getContainer(ec6.getContainerData().getContainerID()).getContainerData().getReplicaIndex(), ec6.getContainerData().getReplicaIndex());
    // for EC container whose entry in DB with replica index -1, is allowed to be loaded
    assertTrue(Files.exists(Paths.get(ec7.getContainerData().getContainerPath())));
    assertEquals(3, mockMetadataStore.getContainerCreateInfoTable().get(ContainerID.valueOf(ec7.getContainerData().getContainerID())).getReplicaIndex());
    // There should be no open containers cached by the ContainerReader as it
    // opens and closed them avoiding the cache.
    assertEquals(0, cache.size());
}

