    containerData.setState(DELETED);
    KeyValueContainer kvContainer = new KeyValueContainer(containerData, conf);
    kvContainer.create(volumeSet, volumeChoosingPolicy, clusterId);
    long baseCount = 0;
    if (containerData.hasSchema(OzoneConsts.SCHEMA_V3)) {
        // add db entry for the container ID 101 for V3
        baseCount = addDbEntry(containerData);
    }
    // verify container data and perform cleanup
    ContainerReader containerReader = new ContainerReader(volumeSet, hddsVolume, containerSet, conf, true);
    containerReader.run();
    // assert that tmp dir is empty
    File[] leftoverContainers = hddsVolume.getDeletedContainerDir().listFiles();
    assertNotNull(leftoverContainers);
    assertEquals(0, leftoverContainers.length);
    assertNull(containerSet.getContainer(101));
    if (containerData.hasSchema(OzoneConsts.SCHEMA_V3)) {
        // verify if newly added container is not present as added
        try (DBHandle dbHandle = BlockUtils.getDB(kvContainer.getContainerData(), conf)) {
            DatanodeStoreSchemaThreeImpl store = (DatanodeStoreSchemaThreeImpl) dbHandle.getStore();
            assertEquals(baseCount, store.getMetadataTable().getEstimatedKeyCount());
        }
    }
}

