public void bufferFlushedWhenFull() throws IOException {
    byte[] bytes = getRandomBytes(bufferSize);
    subject.write(bytes, 0, bufferSize - 1);
    subject.write(bytes[bufferSize - 1]);
    verify(observer).onNext(any());
