@Test
public void testParseHeaders() throws Exception {
    HashMap<String, String> verifyMap = new HashMap<String, String>();
    verifyMap.put("text/plain", HddsConfServlet.FORMAT_XML);
    verifyMap.put(null, HddsConfServlet.FORMAT_XML);
    verifyMap.put("text/xml", HddsConfServlet.FORMAT_XML);
    verifyMap.put("application/xml", HddsConfServlet.FORMAT_XML);
    verifyMap.put("application/json", HddsConfServlet.FORMAT_JSON);
    HttpServletRequest request = mock(HttpServletRequest.class);
    for (Map.Entry<String, String> entry : verifyMap.entrySet()) {
        String contenTypeActual = entry.getValue();
        when(request.getHeader(HttpHeaders.ACCEPT)).thenReturn(entry.getKey());
        assertEquals(contenTypeActual, HddsConfServlet.parseAcceptHeader(request));
    }
}

@Test
void savesValueOnShutdown() {
    AtomicLong savedValue = new AtomicLong(validInitialValue());
    SpaceUsageSource source = mock(SpaceUsageSource.class);
    final long usedSpace = 4L;
    when(source.getUsedSpace()).thenReturn(usedSpace, 5L, 6L);
    SpaceUsageCheckParams params = paramsBuilder(savedValue).withSource(source).build();
    ScheduledFuture<?> future = mock(ScheduledFuture.class);
    ScheduledExecutorService executor = sameThreadExecutorWithoutDelay(future);
    CachingSpaceUsageSource subject = new CachingSpaceUsageSource(params, executor);
    subject.start();
    subject.shutdown();
    assertEquals(usedSpace, savedValue.get(), "value should have been saved to file");
    assertEquals(usedSpace, subject.getUsedSpace(), "no further updates from source expected");
    verify(future, times(2)).cancel(true);
    verify(executor).shutdown();
}

