    versionManager.init(2, lfs);
    assertEquals(2, versionManager.getMetadataLayoutVersion());
    versionManager.finalized(lfs[0]);
    assertEquals(2, versionManager.getMetadataLayoutVersion());
    versionManager.finalized(lfs[1]);
    assertEquals(2, versionManager.getMetadataLayoutVersion());
}

