@Test
public void testClosingRatisWithUnhealthyReplicas() {
    ContainerInfo containerInfo = ReplicationTestUtil.createContainerInfo(RATIS_REPLICATION_CONFIG, 1, CLOSING);
    Set<ContainerReplica> containerReplicas = ReplicationTestUtil.createReplicas(containerInfo.containerID(), ContainerReplicaProto.State.UNHEALTHY, 0, 0, 0);
    ReplicationManagerReport report = new ReplicationManagerReport();
    ContainerCheckRequest request = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(report).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).build();
    subject.handle(request);
    verify(replicationManager, times(1)).updateContainerState(containerInfo.containerID(), QUASI_CLOSE);
    clearInvocations(replicationManager);
    // Now add an open container. This time, the container should not move to
    // quasi-closed, and a close should be sent for the open replica.
    containerReplicas.addAll(ReplicationTestUtil.createReplicas(containerInfo.containerID(), ContainerReplicaProto.State.OPEN, 0));
    assertAndVerify(request, true, 1);
    verify(replicationManager, times(0)).updateContainerState(containerInfo.containerID(), QUASI_CLOSE);
}

