/**
 * Close commands should be sent for Open or Closing replicas.
 */
@ParameterizedTest
@MethodSource("replicationConfigs")
public void testOpenOrClosingReplicasAreClosed(ReplicationConfig repConfig) {
    ContainerInfo containerInfo = ReplicationTestUtil.createContainerInfo(repConfig, 1, CLOSING);
    final int replicas = repConfig.getRequiredNodes();
    final int closing = replicas / 2;
    final boolean force = repConfig.getReplicationType() != RATIS;
    Set<ContainerReplica> containerReplicas = new HashSet<>();
    // Add CLOSING container replicas.
    // For EC, replica index will be in [1, closing].
    for (int i = 1; i <= closing; i++) {
        containerReplicas.add(ReplicationTestUtil.createContainerReplica(containerInfo.containerID(), repConfig.getReplicationType() == EC ? i : 0, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.CLOSING));
    }
    // Add OPEN container replicas.
    // For EC, replica index will be in [closing + 1, replicas].
    for (int i = closing + 1; i <= replicas; i++) {
        containerReplicas.add(ReplicationTestUtil.createContainerReplica(containerInfo.containerID(), repConfig.getReplicationType() == EC ? i : 0, HddsProtos.NodeOperationalState.IN_SERVICE, ContainerReplicaProto.State.OPEN));
    }
    ContainerCheckRequest request = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(containerReplicas).build();
    ArgumentCaptor<Boolean> forceCaptor = ArgumentCaptor.forClass(Boolean.class);
    assertTrue(subject.handle(request));
    verify(replicationManager, times(replicas)).sendCloseContainerReplicaCommand(any(ContainerInfo.class), any(DatanodeDetails.class), forceCaptor.capture());
    forceCaptor.getAllValues().forEach(f -> assertEquals(force, f));
}

