public Set<Pair<DatanodeDetails, SCMCommand<?>>> testUnderReplicationWithMissingIndexes(List<Integer> missingIndexes, Set<ContainerReplica> availableReplicas, int decomIndexes, int maintenanceIndexes, PlacementPolicy placementPolicy) throws IOException {
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(placementPolicy, conf, replicationManager);
    UnderReplicatedHealthResult result = mock(UnderReplicatedHealthResult.class);
    when(result.isUnrecoverable()).thenReturn(false);
    when(result.getContainerInfo()).thenReturn(container);
    ecURH.processAndSendCommands(availableReplicas, ImmutableList.of(), result, remainingMaintenanceRedundancy);
    int replicateCommand = 0;
    int reconstructCommand = 0;
    boolean shouldReconstructCommandExist = !missingIndexes.isEmpty() && missingIndexes.size() <= repConfig.getParity();
    for (Map.Entry<DatanodeDetails, SCMCommand<?>> dnCommand : commandsSent) {
        if (dnCommand.getValue() instanceof ReplicateContainerCommand) {
            replicateCommand++;
        } else if (dnCommand.getValue() instanceof ReconstructECContainersCommand) {
            if (shouldReconstructCommandExist) {
                assertEquals(ECUnderReplicationHandler.integers2ByteString(missingIndexes), ((ReconstructECContainersCommand) dnCommand.getValue()).getMissingContainerIndexes());
            }
            reconstructCommand++;
        }
    }
    int maxMaintenance = PARITY - remainingMaintenanceRedundancy;
    int expectedMaintenanceCommands = Math.max(0, maintenanceIndexes - maxMaintenance);
    assertEquals(decomIndexes + expectedMaintenanceCommands, replicateCommand);
    assertEquals(shouldReconstructCommandExist ? 1 : 0, reconstructCommand);
    return commandsSent;
}

