    assertEquals(0, rm.getReplicationInFlightLimit());
    config.setInflightReplicationLimitFactor(1);
    configuration.setFromObject(config);
    rm = createReplicationManager();
    assertEquals(healthyNodes * config.getDatanodeReplicationLimit(), rm.getReplicationInFlightLimit());
    config.setInflightReplicationLimitFactor(0.75);
    configuration.setFromObject(config);
    rm = createReplicationManager();
    assertEquals((int) Math.ceil(healthyNodes * config.getDatanodeReplicationLimit() * 0.75), rm.getReplicationInFlightLimit());
}

