    verify(publisher, times(0)).fireEvent(eq(SCMEvents.DATANODE_COMMAND), any(CommandForDatanode.class));
}

@Test
public void testUnknownContainerDeleted() {
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(ScmConfig.HDDS_SCM_UNKNOWN_CONTAINER_ACTION, ContainerReportHandler.UnknownContainerAction.DELETE.name());
    sendContainerReport(conf);
    verify(publisher, times(1)).fireEvent(eq(SCMEvents.DATANODE_COMMAND), any(CommandForDatanode.class));
}

/**
 * Trigger datanode to send unknown container report to SCM.
 * @param conf OzoneConfiguration instance to initialize
 *             ContainerReportHandler
 */
private void sendContainerReport(OzoneConfiguration conf) {
    ContainerReportHandler reportHandler = new ContainerReportHandler(nodeManager, containerManager, SCMContext.emptyContext(), conf);
    ContainerInfo container = getContainer(LifeCycleState.CLOSED);
    Iterator<DatanodeDetails> nodeIterator = nodeManager.getNodes(NodeStatus.inServiceHealthy()).iterator();
    DatanodeDetails datanode = nodeIterator.next();
    ContainerReportsProto containerReport = getContainerReportsProto(container.containerID(), ContainerReplicaProto.State.CLOSED, datanode.getUuidString());
    ContainerReportFromDatanode containerReportFromDatanode = new ContainerReportFromDatanode(datanode, containerReport);
    reportHandler.onMessage(containerReportFromDatanode, publisher);
}

@BeforeEach
public void setup() throws IOException, TimeoutException {
    testClock = new TestClock(Instant.now(), ZoneOffset.UTC);
    scmContext = SCMContext.emptyContext();
    this.pipelineManager = mock(PipelineManager.class);
    doNothing().when(pipelineManager).scrubPipelines();
    this.backgroundSCMService = new BackgroundSCMService.Builder().setClock(testClock).setScmContext(scmContext).setServiceName("testBackgroundService").setIntervalInMillis(1L).setWaitTimeInMillis(1L).setPeriodicalTask(() -> {
        try {
            pipelineManager.scrubPipelines();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }).build();
}

@Test
public void testRun() throws IOException {
    assertFalse(backgroundSCMService.shouldRun());
    // kick a run
    synchronized (backgroundSCMService) {
        backgroundSCMService.notifyStatusChanged();
        assertFalse(backgroundSCMService.shouldRun());
        testClock.fastForward(60000);
        assertTrue(backgroundSCMService.shouldRun());
        backgroundSCMService.runImmediately();
    }
    verify(pipelineManager, timeout(3000).atLeastOnce()).scrubPipelines();
}

