@Test
public void testInsufficientNodeMaintenanceThrowsExceptionForRatisAndEc() throws NodeNotFoundException, IOException {
    when(containerManager.getContainer(any(ContainerID.class))).thenAnswer(invocation -> getMockContainer(new ECReplicationConfig(3, 2), (ContainerID) invocation.getArguments()[0]));
    List<DatanodeAdminError> error;
    List<DatanodeDetails> dns = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        DatanodeDetails dn = MockDatanodeDetails.randomDatanodeDetails();
        dns.add(dn);
        nodeManager.register(dn, null, null);
    }
    Set<ContainerID> idsRatis = new HashSet<>();
    ContainerInfo containerRatis = containerManager.allocateContainer(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE), "admin");
    idsRatis.add(containerRatis.containerID());
    Set<ContainerID> idsEC = new HashSet<>();
    ContainerInfo containerEC = containerManager.allocateContainer(new ECReplicationConfig(3, 2), "admin");
    idsEC.add(containerEC.containerID());
    when(containerManager.getContainer(any(ContainerID.class))).thenAnswer(invocation -> {
        ContainerID containerID = (ContainerID) invocation.getArguments()[0];
        if (idsEC.contains(containerID)) {
            return getMockContainer(new ECReplicationConfig(3, 2), (ContainerID) invocation.getArguments()[0]);
        }
        return getMockContainer(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE), (ContainerID) invocation.getArguments()[0]);
    });
    for (DatanodeDetails dn : nodeManager.getAllNodes().subList(0, 3)) {
        setContainers(dn, idsRatis);
    }
    for (DatanodeDetails dn : nodeManager.getAllNodes()) {
        setContainers(dn, idsEC);
    }
    // default config
    decom.setMaintenanceConfigs(2, 1);
    // putting 2 DNs into maintenance leave the cluster with 3 DN,
    // it should not be allowed as maintenance.remaining.redundancy is 1 => 3+1=4 DNs are required
    error = decom.startMaintenanceNodes(Arrays.asList(dns.get(1).getIpAddress(), dns.get(2).getIpAddress()), 100, false);
    assertTrue(error.get(0).getHostname().contains("AllHosts"));
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(1)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(2)).getOperationalState());
    // putting 1 DN into maintenance leave the cluster with 4 DN,
    // it should be allowed
    error = decom.startMaintenanceNodes(Arrays.asList(dns.get(1).getIpAddress()), 100, false);
    assertEquals(0, error.size());
    assertEquals(HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, nodeManager.getNodeStatus(dns.get(1)).getOperationalState());
    decom.recommissionNodes(Arrays.asList(dns.get(1).getIpAddress(), dns.get(2).getIpAddress()));
    decom.getMonitor().run();
    assertEquals(5, nodeManager.getNodeCount(NodeStatus.inServiceHealthy()));
    // non-default config
    decom.setMaintenanceConfigs(3, 2);
    // putting 1 DNs into maintenance leave the cluster with 4 DN,
    // it should not be allowed as for EC, maintenance.remaining.redundancy is 2 => 3+2=5 DNs are required
    error = decom.startMaintenanceNodes(Arrays.asList(dns.get(1).getIpAddress()), 100, false);
    assertTrue(error.get(0).getHostname().contains("AllHosts"));
    String errorMsg = String.format("%d IN-SERVICE HEALTHY and %d not IN-SERVICE or not HEALTHY nodes.", 5, 0);
    assertTrue(error.get(0).getError().contains(errorMsg));
    errorMsg = String.format("Cannot enter maintenance mode as a minimum of %d IN-SERVICE HEALTHY nodes are required", 5);
    assertTrue(error.get(0).getError().contains(errorMsg));
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(1)).getOperationalState());
    decom.recommissionNodes(Arrays.asList(dns.get(1).getIpAddress(), dns.get(2).getIpAddress()));
    decom.getMonitor().run();
    assertEquals(5, nodeManager.getNodeCount(NodeStatus.inServiceHealthy()));
    // forcing 2 DNs into maintenance should be allowed
    error = decom.startMaintenanceNodes(Arrays.asList(dns.get(1).getIpAddress(), dns.get(2).getIpAddress()), 100, true);
    assertEquals(0, error.size());
    assertEquals(HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, nodeManager.getNodeStatus(dns.get(1)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, nodeManager.getNodeStatus(dns.get(2)).getOperationalState());
}

