public void testInsufficientNodeMaintenanceChecksForNNF() throws NodeNotFoundException, IOException {
    List<DatanodeAdminError> error;
    List<DatanodeDetails> dns = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        DatanodeDetails dn = MockDatanodeDetails.randomDatanodeDetails();
        dns.add(dn);
    }
    Set<ContainerID> idsRatis = new HashSet<>();
    for (int i = 0; i < 3; i++) {
        ContainerInfo container = containerManager.allocateContainer(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE), "admin");
        idsRatis.add(container.containerID());
    }
    nodeManager = mock(SCMNodeManager.class);
    decom = new NodeDecommissionManager(conf, nodeManager, containerManager, SCMContext.emptyContext(), new EventQueue(), null);
    when(containerManager.getContainer(any(ContainerID.class))).thenAnswer(invocation -> getMockContainer(RatisReplicationConfig.getInstance(HddsProtos.ReplicationFactor.THREE), (ContainerID) invocation.getArguments()[0]));
    when(nodeManager.getNodesByAddress(any())).thenAnswer(invocation -> getDatanodeDetailsList((String) invocation.getArguments()[0], dns));
    when(nodeManager.getContainers(any())).thenReturn(idsRatis);
    when(nodeManager.getNodeCount(any())).thenReturn(5);
    when(nodeManager.getNodeStatus(any())).thenAnswer(invocation -> getNodeOpState((DatanodeDetails) invocation.getArguments()[0], dns));
    Mockito.doAnswer(invocation -> {
        setNodeOpState((DatanodeDetails) invocation.getArguments()[0], (HddsProtos.NodeOperationalState) invocation.getArguments()[1], dns);
        return null;
    }).when(nodeManager).setNodeOperationalState(any(DatanodeDetails.class), any(HddsProtos.NodeOperationalState.class));
    Mockito.doAnswer(invocation -> {
        setNodeOpState((DatanodeDetails) invocation.getArguments()[0], (HddsProtos.NodeOperationalState) invocation.getArguments()[1], dns);
        return null;
    }).when(nodeManager).setNodeOperationalState(any(DatanodeDetails.class), any(HddsProtos.NodeOperationalState.class), any(Long.class));
    // trying to put 4 available DNs into maintenance,
    // it should not be allowed as it leaves the cluster with 1 DN and maintenance.replica.minimum is 2
    error = decom.startMaintenanceNodes(Arrays.asList(dns.get(1).getIpAddress(), dns.get(2).getIpAddress(), dns.get(3).getIpAddress(), dns.get(4).getIpAddress()), 100, false);
    assertTrue(error.get(0).getHostname().contains("AllHosts"));
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(1)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(2)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(3)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.IN_SERVICE, nodeManager.getNodeStatus(dns.get(4)).getOperationalState());
    // trying to put 4 DNs (3 available + 1 not found) into maintenance,
    // it should be allowed as effectively, it tries to move 3 DNs to maintenance,
    // leaving the cluster with 2 DNs
    error = decom.startMaintenanceNodes(Arrays.asList(dns.get(0).getIpAddress(), dns.get(1).getIpAddress(), dns.get(2).getIpAddress(), dns.get(3).getIpAddress()), 100, false);
    assertEquals(0, error.size());
    assertEquals(HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, nodeManager.getNodeStatus(dns.get(1)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, nodeManager.getNodeStatus(dns.get(2)).getOperationalState());
    assertEquals(HddsProtos.NodeOperationalState.ENTERING_MAINTENANCE, nodeManager.getNodeStatus(dns.get(3)).getOperationalState());
}

