/**
 * {@link PipelineManager#hasEnoughSpace(Pipeline, long)} should return false if all the
 * volumes on any Datanode in the pipeline have less than equal to the space required for creating a new container.
 */
@Test
public void testHasEnoughSpace() throws IOException {
    // create a Mock NodeManager, the MockNodeManager class doesn't work for this test
    NodeManager mockedNodeManager = Mockito.mock(NodeManager.class);
    PipelineManagerImpl pipelineManager = PipelineManagerImpl.newPipelineManager(conf, SCMHAManagerStub.getInstance(true), mockedNodeManager, SCMDBDefinition.PIPELINES.getTable(dbStore), new EventQueue(), scmContext, serviceManager, testClock);
    Pipeline pipeline = Pipeline.newBuilder().setId(PipelineID.randomId()).setNodes(ImmutableList.of(MockDatanodeDetails.randomDatanodeDetails(), MockDatanodeDetails.randomDatanodeDetails(), MockDatanodeDetails.randomDatanodeDetails())).setState(OPEN).setReplicationConfig(ReplicationConfig.fromTypeAndFactor(ReplicationType.RATIS, THREE)).build();
    List<DatanodeDetails> nodes = pipeline.getNodes();
    assertEquals(3, nodes.size());
    long containerSize = 100L;
    // Case 1: All nodes have enough space.
    List<DatanodeInfo> datanodeInfoList = new ArrayList<>();
    for (DatanodeDetails dn : nodes) {
        // the method being tested needs NodeManager to return DatanodeInfo because DatanodeInfo has storage
        // information (it extends DatanodeDetails)
        DatanodeInfo info = new DatanodeInfo(dn, null, null);
        info.updateStorageReports(HddsTestUtils.createStorageReports(dn.getID(), 200L, 200L, 10L));
        doReturn(info).when(mockedNodeManager).getDatanodeInfo(dn);
        datanodeInfoList.add(info);
    }
    assertTrue(pipelineManager.hasEnoughSpace(pipeline, containerSize));
    // Case 2: One node does not have enough space.
    /*
     Interestingly, SCMCommonPlacementPolicy#hasEnoughSpace returns false if exactly the required amount of space
      is available. Which means it won't allow creating a pipeline on a node if all volumes have exactly 5 GB
      available. We follow the same behavior here in the case of a new replica.

      So here, remaining - committed == containerSize, and hasEnoughSpace returns false.
      TODO should this return true instead?
     */
    DatanodeInfo datanodeInfo = datanodeInfoList.get(0);
    datanodeInfo.updateStorageReports(HddsTestUtils.createStorageReports(datanodeInfo.getID(), 200L, 120L, 20L));
    assertFalse(pipelineManager.hasEnoughSpace(pipeline, containerSize));
    // Case 3: All nodes do not have enough space.
    for (DatanodeInfo info : datanodeInfoList) {
        info.updateStorageReports(HddsTestUtils.createStorageReports(info.getID(), 200L, 100L, 20L));
    }
    assertFalse(pipelineManager.hasEnoughSpace(pipeline, containerSize));
}

private void setupRacks(int datanodeCount, int nodesPerRack, boolean firstRackLessNode) throws Exception {
    conf.setStorageSize(OZONE_DATANODE_RATIS_VOLUME_FREE_SPACE_MIN, 1, StorageUnit.BYTES);
    NodeSchema[] schemas = new NodeSchema[] { ROOT_SCHEMA, RACK_SCHEMA, LEAF_SCHEMA };
    NodeSchemaManager.getInstance().init(schemas, true);
    cluster = new NetworkTopologyImpl(NodeSchemaManager.getInstance());
    // build datanodes, and network topology
    String rack = "/rack";
    String hostname = "node";
    for (int i = 0; i < datanodeCount; i++) {
        DatanodeDetails datanodeDetails = MockDatanodeDetails.createDatanodeDetails(hostname + i, firstRackLessNode ? rack + ((i + 1) / nodesPerRack) : rack + (i / nodesPerRack));
        datanodes.add(datanodeDetails);
        cluster.add(datanodeDetails);
        DatanodeInfo datanodeInfo = new DatanodeInfo(datanodeDetails, NodeStatus.inServiceHealthy(), UpgradeUtils.defaultLayoutVersionProto());
        StorageContainerDatanodeProtocolProtos.StorageReportProto storage1 = HddsTestUtils.createStorageReport(datanodeInfo.getID(), "/data1-" + datanodeInfo.getID(), STORAGE_CAPACITY, 0, 100L, null);
        StorageContainerDatanodeProtocolProtos.MetadataStorageReportProto metaStorage1 = HddsTestUtils.createMetadataStorageReport("/metadata1-" + datanodeInfo.getID(), STORAGE_CAPACITY, 0, 100L, null);
        datanodeInfo.updateStorageReports(new ArrayList<>(Arrays.asList(storage1)));
        datanodeInfo.updateMetaDataStorageReports(new ArrayList<>(Arrays.asList(metaStorage1)));
        dnInfos.add(datanodeInfo);
    }
    NodeManager nodeManagerBase = new MockNodeManager(cluster, datanodes, false, 10);
    nodeManager = spy(nodeManagerBase);
    for (DatanodeInfo dn : dnInfos) {
        when(nodeManager.getNode(dn.getID())).thenReturn(dn);
    }
    DBStore dbStore = DBStoreBuilder.createDBStore(conf, SCMDBDefinition.get());
    SCMHAManager scmhaManager = SCMHAManagerStub.getInstance(true);
    stateManager = PipelineStateManagerImpl.newBuilder().setPipelineStore(SCMDBDefinition.PIPELINES.getTable(dbStore)).setRatisServer(scmhaManager.getRatisServer()).setNodeManager(nodeManager).setSCMDBTransactionBuffer(scmhaManager.getDBTransactionBuffer()).build();
}

