        Pipeline pipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
        pipelineManager.openPipeline(pipeline.getId());
        pipeline = pipelineManager.getPipeline(pipeline.getId());
        MockRatisPipelineProvider.markPipelineHealthy(pipeline);
        // Mark one DN as DEAD
        DatanodeDetails dnDead = pipeline.getNodes().get(0);
        nodeManager.setNodeState(dnDead, HddsProtos.NodeState.DEAD);
        SCMSafeModeManager scmSafeModeManager = new SCMSafeModeManager(config, nodeManager, pipelineManager, containerManager, serviceManager, eventQueue, scmContext);
        scmSafeModeManager.start();
        LogCapturer logCapturer = LogCapturer.captureLogs(HealthyPipelineSafeModeRule.class);
