@ParameterizedTest
@MethodSource("testCaseForSafeModeExitRuleWithPipelineAvailabilityCheck")
public void testSafeModeExitRuleWithPipelineAvailabilityCheck(int containerCount, int nodeCount, int pipelineCount, double healthyPipelinePercent, double oneReplicaPercent) throws Exception {
    OzoneConfiguration conf = createConf(healthyPipelinePercent, oneReplicaPercent);
    containers = new ArrayList<>();
    containers.addAll(HddsTestUtils.getContainerInfo(containerCount));
    MockNodeManager mockNodeManager = new MockNodeManager(true, nodeCount);
    PipelineManagerImpl pipelineManager = PipelineManagerImpl.newPipelineManager(conf, SCMHAManagerStub.getInstance(true), mockNodeManager, scmMetadataStore.getPipelineTable(), queue, scmContext, serviceManager, Clock.system(ZoneOffset.UTC));
    PipelineProvider<RatisReplicationConfig> mockRatisProvider = new MockRatisPipelineProvider(mockNodeManager, pipelineManager.getStateManager(), config);
    pipelineManager.setPipelineProvider(HddsProtos.ReplicationType.RATIS, mockRatisProvider);
    pipelineManager.getBackgroundPipelineCreator().stop();
    pipelineManager.getBackgroundPipelineScrubber().stop();
    for (int i = 0; i < pipelineCount; i++) {
        // Create pipeline
        Pipeline pipeline = pipelineManager.createPipeline(RatisReplicationConfig.getInstance(ReplicationFactor.THREE));
        pipelineManager.openPipeline(pipeline.getId());
        // Mark pipeline healthy
        pipeline = pipelineManager.getPipeline(pipeline.getId());
        MockRatisPipelineProvider.markPipelineHealthy(pipeline);
    }
    for (ContainerInfo container : containers) {
        container.setState(HddsProtos.LifeCycleState.CLOSED);
    }
    ContainerManager containerManager = mock(ContainerManager.class);
    when(containerManager.getContainers(ReplicationType.RATIS)).thenReturn(containers);
    scmSafeModeManager = new SCMSafeModeManager(conf, mockNodeManager, pipelineManager, containerManager, serviceManager, queue, scmContext);
    scmSafeModeManager.start();
    assertTrue(scmSafeModeManager.getInSafeMode());
    if (healthyPipelinePercent > 0) {
        validateRuleStatus("HealthyPipelineSafeModeRule", "healthy Ratis/THREE pipelines");
    }
    validateRuleStatus("OneReplicaPipelineSafeModeRule", "reported Ratis/THREE pipelines with at least one datanode");
    testContainerThreshold(containers, 1.0);
    List<Pipeline> pipelines = pipelineManager.getPipelines();
    int healthyPipelineThresholdCount = SafeModeRuleFactory.getInstance().getSafeModeRule(HealthyPipelineSafeModeRule.class).getHealthyPipelineThresholdCount();
    int oneReplicaThresholdCount = SafeModeRuleFactory.getInstance().getSafeModeRule(OneReplicaPipelineSafeModeRule.class).getThresholdCount();
    assertEquals(healthyPipelineThresholdCount, scmSafeModeManager.getSafeModeMetrics().getNumHealthyPipelinesThreshold().value());
    assertEquals(oneReplicaThresholdCount, scmSafeModeManager.getSafeModeMetrics().getNumPipelinesWithAtleastOneReplicaReportedThreshold().value());
    // Because even if no pipelines are there, and threshold we set to zero,
    // we shall a get an event when datanode is registered. In that case,
    // validate will return true, and add this to validatedRules.
    if (Math.max(healthyPipelinePercent, oneReplicaThresholdCount) == 0) {
        firePipelineEvent(pipelineManager, pipelines.get(0));
    }
