private void parseArgsAndExecute(String... args) throws Exception {
    // Create fresh streams and command objects for each execution, otherwise stale results may interfere with tests.
    if (inContent != null) {
        inContent.reset();
    }
    outContent.reset();
    errContent.reset();
    System.setOut(new PrintStream(outContent, false, DEFAULT_ENCODING));
    System.setErr(new PrintStream(errContent, false, DEFAULT_ENCODING));
    ReconcileSubcommand cmd = new ReconcileSubcommand();
    new CommandLine(cmd).parseArgs(args);
    cmd.execute(scmClient);
}

private void mockContainer(long containerID, int numReplicas, ReplicationConfig repConfig, HddsProtos.LifeCycleState state, boolean replicasMatch) throws Exception {
    ContainerInfo container = new ContainerInfo.Builder().setContainerID(containerID).setState(state).setReplicationConfig(repConfig).build();
    when(scmClient.getContainer(containerID)).thenReturn(container);
    List<ContainerReplicaInfo> replicas = new ArrayList<>();
    int replicaIndex = 1;
    for (int i = 0; i < numReplicas; i++) {
        DatanodeDetails dn = DatanodeDetails.newBuilder().setHostName("dn").setUuid(UUID.randomUUID()).setIpAddress("127.0.0.1").build();
        ContainerReplicaInfo.Builder replicaBuilder = new ContainerReplicaInfo.Builder().setContainerID(containerID).setState(state.name()).setDatanodeDetails(dn);
        if (repConfig.getReplicationType() != HddsProtos.ReplicationType.RATIS) {
            replicaBuilder.setReplicaIndex(replicaIndex++);
        }
        if (replicasMatch) {
            if (state == OPEN) {
                replicaBuilder.setDataChecksum(0);
            } else {
                replicaBuilder.setDataChecksum(123);
            }
        } else {
            replicaBuilder.setDataChecksum(i);
        }
        replicas.add(replicaBuilder.build());
    }
    when(scmClient.getContainerReplicas(containerID)).thenReturn(replicas);
}

private void mockContainer(long containerID, int numReplicas, ReplicationConfig repConfig, HddsProtos.LifeCycleState state, boolean replicasMatch) throws Exception {
    ContainerInfo container = new ContainerInfo.Builder().setContainerID(containerID).setState(state).setReplicationConfig(repConfig).build();
    when(scmClient.getContainer(containerID)).thenReturn(container);
    List<ContainerReplicaInfo> replicas = new ArrayList<>();
    int replicaIndex = 1;
    for (int i = 0; i < numReplicas; i++) {
        DatanodeDetails dn = DatanodeDetails.newBuilder().setHostName("dn").setUuid(UUID.randomUUID()).setIpAddress("127.0.0.1").build();
        ContainerReplicaInfo.Builder replicaBuilder = new ContainerReplicaInfo.Builder().setContainerID(containerID).setState(state.name()).setDatanodeDetails(dn);
        if (repConfig.getReplicationType() != HddsProtos.ReplicationType.RATIS) {
            replicaBuilder.setReplicaIndex(replicaIndex++);
        }
        if (replicasMatch) {
            if (state == OPEN) {
                replicaBuilder.setDataChecksum(0);
            } else {
                replicaBuilder.setDataChecksum(123);
            }
        } else {
            replicaBuilder.setDataChecksum(i);
        }
        replicas.add(replicaBuilder.build());
    }
    when(scmClient.getContainerReplicas(containerID)).thenReturn(replicas);
}

