    try (CapableOzoneFSOutputStream cofsos = new CapableOzoneFSOutputStream(ofso, true)) {
        if (isEC) {
            assertFalse(cofsos.hasCapability(StreamCapabilities.HFLUSH));
        } else {
            assertTrue(cofsos.hasCapability(StreamCapabilities.HFLUSH));
        }
    }
    try (CapableOzoneFSOutputStream cofsos = new CapableOzoneFSOutputStream(ofso, false)) {
        assertFalse(cofsos.hasCapability(StreamCapabilities.HFLUSH));
    }
}

