private void testRpcPermission(MiniOzoneCluster cluster, String fakeRemoteUsername, boolean expectPermissionDenied) {
    SCMClientProtocolServer mockClientServer = spy(cluster.getStorageContainerManager().getClientProtocolServer());
    mockRemoteUser(UserGroupInformation.createRemoteUser(fakeRemoteUsername));
    Exception ex = assertThrows(Exception.class, () -> mockClientServer.deleteContainer(ContainerTestHelper.getTestContainerID()));
    if (expectPermissionDenied) {
        verifyPermissionDeniedException(ex, fakeRemoteUsername);
    } else {
        // If passes permission check, it should fail with
        // container not exist exception.
        assertInstanceOf(ContainerNotFoundException.class, ex);
    }
    if (expectPermissionDenied) {
        Exception allocateException = assertThrows(Exception.class, () -> mockClientServer.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, OzoneConsts.OZONE));
        verifyPermissionDeniedException(allocateException, fakeRemoteUsername);
    } else {
        // If not expecting permission denied, validate the successful operation's result
        ContainerWithPipeline container2 = assertDoesNotThrow(() -> mockClientServer.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, OzoneConsts.OZONE));
        assertEquals(1, container2.getPipeline().getNodes().size());
    }
    Exception e = assertThrows(Exception.class, () -> mockClientServer.getContainer(ContainerTestHelper.getTestContainerID()));
    if (expectPermissionDenied) {
        verifyPermissionDeniedException(e, fakeRemoteUsername);
    } else {
        // If passes permission check, it should fail with
        // key not exist exception.
        assertInstanceOf(ContainerNotFoundException.class, e);
    }
}

@Test
public void testContainerReportQueueWithDrop() throws Exception {
    EventQueue eventQueue = new EventQueue();
    List<BlockingQueue<SCMDatanodeHeartbeatDispatcher.ContainerReport>> queues = new ArrayList<>();
    for (int i = 0; i < 1; ++i) {
        queues.add(new ContainerReportQueue());
    }
    ContainerReportsProto report = ContainerReportsProto.getDefaultInstance();
    DatanodeDetails dn = DatanodeDetails.newBuilder().setID(DatanodeID.randomID()).build();
    ContainerReportFromDatanode dndata = new ContainerReportFromDatanode(dn, report);
    ContainerReportHandler containerReportHandler = mock(ContainerReportHandler.class);
    doAnswer((inv) -> {
        Thread.sleep(500);
        return null;
    }).when(containerReportHandler).onMessage(dndata, eventQueue);
    List<ThreadPoolExecutor> executors = FixedThreadPoolWithAffinityExecutor.initializeExecutorPool(queues);
    Map<String, FixedThreadPoolWithAffinityExecutor> reportExecutorMap = new ConcurrentHashMap<>();
    EventExecutor<ContainerReportFromDatanode> containerReportExecutors = new FixedThreadPoolWithAffinityExecutor<>(EventQueue.getExecutorName(SCMEvents.CONTAINER_REPORT, containerReportHandler), containerReportHandler, queues, eventQueue, ContainerReportFromDatanode.class, executors, reportExecutorMap);
    eventQueue.addHandler(SCMEvents.CONTAINER_REPORT, containerReportExecutors, containerReportHandler);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.CONTAINER_REPORT, dndata);
    assertThat(containerReportExecutors.droppedEvents()).isGreaterThan(1);
    Thread.sleep(1000);
    assertEquals(containerReportExecutors.droppedEvents() + containerReportExecutors.scheduledEvents(), containerReportExecutors.queuedEvents());
    containerReportExecutors.close();
}

