    List<BlockingQueue<SCMDatanodeHeartbeatDispatcher.ContainerReport>> queues = new ArrayList<>();
    for (int i = 0; i < 1; ++i) {
        queues.add(new ContainerReportQueue());
    }
    DatanodeDetails dn = DatanodeDetails.newBuilder().setID(DatanodeID.randomID()).build();
    IncrementalContainerReportProto report = IncrementalContainerReportProto.getDefaultInstance();
    IncrementalContainerReportFromDatanode dndata = new IncrementalContainerReportFromDatanode(dn, report);
    IncrementalContainerReportHandler icr = mock(IncrementalContainerReportHandler.class);
    doAnswer((inv) -> {
        Thread.sleep(500);
        return null;
    }).when(icr).onMessage(dndata, eventQueue);
    List<ThreadPoolExecutor> executors = FixedThreadPoolWithAffinityExecutor.initializeExecutorPool(queues);
    Map<String, FixedThreadPoolWithAffinityExecutor> reportExecutorMap = new ConcurrentHashMap<>();
    EventExecutor<IncrementalContainerReportFromDatanode> containerReportExecutors = new FixedThreadPoolWithAffinityExecutor<>(EventQueue.getExecutorName(SCMEvents.INCREMENTAL_CONTAINER_REPORT, icr), icr, queues, eventQueue, IncrementalContainerReportFromDatanode.class, executors, reportExecutorMap);
    eventQueue.addHandler(SCMEvents.INCREMENTAL_CONTAINER_REPORT, containerReportExecutors, icr);
    eventQueue.fireEvent(SCMEvents.INCREMENTAL_CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.INCREMENTAL_CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.INCREMENTAL_CONTAINER_REPORT, dndata);
    eventQueue.fireEvent(SCMEvents.INCREMENTAL_CONTAINER_REPORT, dndata);
    assertEquals(0, containerReportExecutors.droppedEvents());
    Thread.sleep(3000);
    assertEquals(containerReportExecutors.scheduledEvents(), containerReportExecutors.queuedEvents());
    containerReportExecutors.close();
}

