    mockPutBlockResponse(mockDn1Protocol, CONTAINER_ID.get(), 1L, data);
    OzoneBucket bucket = objectStore.getVolume(VOLUME_NAME).getBucket(BUCKET_NAME);
    String keyName = "key";
    try (OzoneOutputStream os = bucket.createKey(keyName, data.length)) {
