    ContainerInfo containerInfo = new ContainerInfo.Builder().setContainerID(containerId).setPipelineID(pipeline.getId()).build();
    List<ContainerWithPipeline> containerWithPipelines = Collections.singletonList(new ContainerWithPipeline(containerInfo, pipeline));
    when(mockScmContainerClient.getContainerWithPipelineBatch(newHashSet(containerId))).thenReturn(containerWithPipelines);
}

private void mockScmGetContainerPipelineEmpty(long containerId) throws IOException {
    Pipeline pipeline = createPipeline(Collections.emptyList());
    ContainerInfo containerInfo = new ContainerInfo.Builder().setContainerID(containerId).setPipelineID(pipeline.getId()).build();
    List<ContainerWithPipeline> containerWithPipelines = Collections.singletonList(new ContainerWithPipeline(containerInfo, pipeline));
    when(mockScmContainerClient.getContainerWithPipelineBatch(newHashSet(containerId))).thenReturn(containerWithPipelines);
}

private void mockScmGetContainerEcPipeline(long containerId, Map<DatanodeDetails, Integer> indexes) throws IOException {
    Pipeline pipeline = createEcPipeline(indexes);
    ContainerInfo containerInfo = new ContainerInfo.Builder().setContainerID(containerId).setPipelineID(pipeline.getId()).build();
    List<ContainerWithPipeline> containerWithPipelines = Collections.singletonList(new ContainerWithPipeline(containerInfo, pipeline));
    when(mockScmContainerClient.getContainerWithPipelineBatch(newHashSet(containerId))).thenReturn(containerWithPipelines);
}

