    assertEquals(initialCheckpointSet, finalCheckpointSet);
    String shortSnapshotLocation = truncateFileName(metaDirLength, Paths.get(snapshotDirName));
    String shortSnapshotLocation2 = truncateFileName(metaDirLength, Paths.get(snapshotDirName2));
    String shortCompactionDirLocation = truncateFileName(metaDirLength, compactionDirPath);
    Set<String> finalFullSet = getFiles(Paths.get(testDirName, OM_SNAPSHOT_DIR), testDirLength);
