private void testBootstrapLocking() throws Exception {
    // Get the bootstrap state handlers
    KeyManager keyManager = om.getKeyManager();
    BootstrapStateHandler keyDeletingService = keyManager.getDeletingService();
    BootstrapStateHandler snapshotDeletingService = keyManager.getSnapshotDeletingService();
    BootstrapStateHandler sstFilteringService = keyManager.getSnapshotSstFilteringService();
    BootstrapStateHandler differ = om.getMetadataManager().getStore().getRocksDBCheckpointDiffer();
    ExecutorService executorService = Executors.newCachedThreadPool();
    OMDBCheckpointServlet omDbCheckpointServlet = new OMDBCheckpointServlet();
    OMDBCheckpointServlet spyServlet = spy(omDbCheckpointServlet);
    ServletContext servletContext = mock(ServletContext.class);
    when(servletContext.getAttribute(OzoneConsts.OM_CONTEXT_ATTRIBUTE)).thenReturn(om);
    doReturn(servletContext).when(spyServlet).getServletContext();
    spyServlet.init();
    // Confirm the other handlers are locked out when the bootstrap
    //  servlet takes the lock.
    try (BootstrapStateHandler.Lock ignoredLock = spyServlet.getBootstrapStateLock().lock()) {
        confirmServletLocksOutOtherHandler(keyDeletingService, executorService);
        confirmServletLocksOutOtherHandler(snapshotDeletingService, executorService);
        confirmServletLocksOutOtherHandler(sstFilteringService, executorService);
        confirmServletLocksOutOtherHandler(differ, executorService);
    }
    // Confirm the servlet is locked out when any of the other
    //  handlers takes the lock.
    confirmOtherHandlerLocksOutServlet(keyDeletingService, spyServlet, executorService);
    confirmOtherHandlerLocksOutServlet(snapshotDeletingService, spyServlet, executorService);
    confirmOtherHandlerLocksOutServlet(sstFilteringService, spyServlet, executorService);
    confirmOtherHandlerLocksOutServlet(differ, spyServlet, executorService);
    // Confirm that servlet takes the lock when none of the other
    //  handlers have it.
    Future<Boolean> servletTest = checkLock(spyServlet, executorService);
    assertTrue(servletTest.get(10000, TimeUnit.MILLISECONDS));
    executorService.shutdownNow();
}

