private void setupClusterAndMocks(String volumeName, String bucketName, AtomicReference<DBCheckpoint> realCheckpoint, boolean includeSnapshots) throws Exception {
    setupCluster();
    setupMocks();
    om.getKeyManager().getSnapshotSstFilteringService().pause();
    when(requestMock.getParameter(OZONE_DB_CHECKPOINT_INCLUDE_SNAPSHOT_DATA)).thenReturn(String.valueOf(includeSnapshots));
    // Create a "spy" dbstore keep track of the checkpoint.
    writeData(volumeName, bucketName, true);
    DBStore dbStore = om.getMetadataManager().getStore();
    DBStore spyDbStore = spy(dbStore);
    when(spyDbStore.getCheckpoint(true)).thenAnswer(b -> {
        DBCheckpoint checkpoint = spy(dbStore.getCheckpoint(true));
        // Don't delete the checkpoint, because we need to compare it
        // with the snapshot data.
        doNothing().when(checkpoint).cleanupCheckpoint();
        realCheckpoint.set(checkpoint);
        return checkpoint;
    });
    // Init the mock with the spyDbstore
    doCallRealMethod().when(omDbCheckpointServletMock).initialize(any(), any(), eq(false), any(), any(), eq(false));
    omDbCheckpointServletMock.initialize(spyDbStore, om.getMetrics().getDBCheckpointMetrics(), false, om.getOmAdminUsernames(), om.getOmAdminGroups(), false);
    when(responseMock.getOutputStream()).thenReturn(servletOutputStream);
}

