@BeforeAll
public static void setup() throws Exception {
    config = new OzoneConfiguration();
    config.set(HddsConfigKeys.OZONE_METADATA_DIRS, dir.toString());
    config.set(NET_TOPOLOGY_NODE_SWITCH_MAPPING_IMPL_KEY, StaticMapping.class.getName());
    config.set(OzoneConfigKeys.OZONE_NETWORK_TOPOLOGY_AWARE_READ_KEY, "true");
    List<DatanodeDetails> datanodes = new ArrayList<>(NODE_COUNT);
    List<String> nodeMapping = new ArrayList<>(NODE_COUNT);
    for (int i = 0; i < NODE_COUNT; i++) {
        DatanodeDetails dn = randomDatanodeDetails();
        final String rack = "/rack" + (i % 2);
        nodeMapping.add(dn.getHostName() + "=" + rack);
        nodeMapping.add(dn.getIpAddress() + "=" + rack);
        datanodes.add(dn);
    }
    EDGE_NODES.forEach((n, r) -> nodeMapping.add(n + "=" + r));
    config.set(StaticMapping.KEY_HADOOP_CONFIGURED_NODE_MAPPING, String.join(",", nodeMapping));
    SCMConfigurator configurator = new SCMConfigurator();
    configurator.setSCMHAManager(SCMHAManagerStub.getInstance(true));
    configurator.setScmContext(SCMContext.emptyContext());
    scm = HddsTestUtils.getScm(config, configurator);
    scm.start();
    scm.exitSafeMode();
    nodeManager = scm.getScmNodeManager();
    datanodes.forEach(dn -> nodeManager.register(dn, null, null));
    StorageContainerLocationProtocol mockScmContainerClient = mock(StorageContainerLocationProtocol.class);
    OmTestManagers omTestManagers = new OmTestManagers(config, scm.getBlockProtocolServer(), mockScmContainerClient);
    om = omTestManagers.getOzoneManager();
    ozoneClient = omTestManagers.getRpcClient();
    keyManager = (KeyManagerImpl) omTestManagers.getKeyManager();
}

/**
 * Test successful certificate rotation.
 */
@Test
void testCertificateRotation() throws Exception {
    OMStorage omStorage = new OMStorage(conf);
    omStorage.setClusterId(clusterId);
    omStorage.setOmId(omId);
    OzoneManager.setTestSecureOmFlag(true);
    SecurityConfig securityConfig = new SecurityConfig(conf);
    // save first cert
    // seconds
    final int certificateLifetime = 20;
    KeyStorage keyStorage = new KeyStorage(securityConfig, "om");
    X509Certificate cert = generateSelfSignedX509Cert(securityConfig, keyStorage.readKeyPair(), null, Duration.ofSeconds(certificateLifetime));
    String certId = cert.getSerialNumber().toString();
    omStorage.setOmCertSerialId(certId);
    omStorage.forceInitialize();
    CertificateCodec certCodec = new CertificateCodec(securityConfig, "om");
    certCodec.writeCertificate(cert);
    String caCertFileName = CAType.ROOT.getFileNamePrefix() + cert.getSerialNumber().toString() + ".crt";
    certCodec.writeCertificate(cert, caCertFileName);
    // first renewed cert
    X509Certificate newCert = generateSelfSignedX509Cert(securityConfig, null, LocalDateTime.now().plus(securityConfig.getRenewalGracePeriod()), Duration.ofSeconds(certificateLifetime));
    String pemCert = CertificateCodec.getPEMEncodedString(newCert);
    SCMGetCertResponseProto responseProto = SCMGetCertResponseProto.newBuilder().setResponseCode(SCMSecurityProtocolProtos.SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).setX509CACertificate(pemCert).build();
    SCMSecurityProtocolClientSideTranslatorPB scmClient = mock(SCMSecurityProtocolClientSideTranslatorPB.class);
    when(scmClient.getOMCertChain(any(), anyString())).thenReturn(responseProto);
    try (OMCertificateClient client = new OMCertificateClient(securityConfig, scmClient, omStorage, omInfo, "", scmId, null, null)) {
        client.init();
        // create Ozone Manager instance, it will start the monitor task
        conf.set(OZONE_SCM_CLIENT_ADDRESS_KEY, "localhost");
        om = OzoneManager.createOm(conf);
        om.setScmTopologyClient(new ScmTopologyClient(scmBlockClient));
        om.setCertClient(client);
        // check after renew, client will have the new cert ID
        String id1 = newCert.getSerialNumber().toString();
        GenericTestUtils.waitFor(() -> id1.equals(client.getCertificate().getSerialNumber().toString()), 1000, certificateLifetime * 1000);
        // test the second time certificate rotation
        // second renewed cert
        newCert = generateSelfSignedX509Cert(securityConfig, null, null, Duration.ofSeconds(certificateLifetime));
        pemCert = CertificateCodec.getPEMEncodedString(newCert);
        responseProto = SCMGetCertResponseProto.newBuilder().setResponseCode(SCMSecurityProtocolProtos.SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).setX509CACertificate(pemCert).build();
        when(scmClient.getOMCertChain(any(), anyString())).thenReturn(responseProto);
        String id2 = newCert.getSerialNumber().toString();
        // check after renew, client will have the new cert ID
        GenericTestUtils.waitFor(() -> id2.equals(client.getCertificate().getSerialNumber().toString()), 1000, certificateLifetime * 1000);
    }
}

