/**
 * Test unexpected SCMGetCertResponseProto returned from SCM.
 */
@Test
void testCertificateRotationRecoverableFailure() throws Exception {
    LogCapturer omLogs = LogCapturer.captureLogs(OMCertificateClient.class);
    OMStorage omStorage = new OMStorage(conf);
    omStorage.setClusterId(clusterId);
    omStorage.setOmId(omId);
    OzoneManager.setTestSecureOmFlag(true);
    SecurityConfig securityConfig = new SecurityConfig(conf);
    CertificateCodec certCodec = new CertificateCodec(securityConfig, "om");
    // save first cert
    // seconds
    final int certificateLifetime = 20;
    KeyStorage keyStorage = new KeyStorage(securityConfig, "om");
    X509Certificate certHolder = generateSelfSignedX509Cert(securityConfig, keyStorage.readKeyPair(), null, Duration.ofSeconds(certificateLifetime));
    String certId = certHolder.getSerialNumber().toString();
    certCodec.writeCertificate(certHolder);
    omStorage.setOmCertSerialId(certId);
    omStorage.forceInitialize();
    // prepare a mocked scmClient to certificate signing
    SCMSecurityProtocolClientSideTranslatorPB scmClient = mock(SCMSecurityProtocolClientSideTranslatorPB.class);
    Duration gracePeriod = securityConfig.getRenewalGracePeriod();
    X509Certificate newCertHolder = generateSelfSignedX509Cert(securityConfig, null, LocalDateTime.now().plus(gracePeriod), Duration.ofSeconds(certificateLifetime));
    String pemCert = CertificateCodec.getPEMEncodedString(newCertHolder);
    // provide an invalid SCMGetCertResponseProto. Without
    // setX509CACertificate(pemCert), signAndStoreCert will throw exception.
    SCMSecurityProtocolProtos.SCMGetCertResponseProto responseProto = SCMSecurityProtocolProtos.SCMGetCertResponseProto.newBuilder().setResponseCode(SCMSecurityProtocolProtos.SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).build();
    when(scmClient.getOMCertChain(any(), anyString())).thenReturn(responseProto);
    try (OMCertificateClient client = new OMCertificateClient(securityConfig, scmClient, omStorage, omInfo, "", scmId, null, null)) {
        client.init();
        // check that new cert ID should not equal to current cert ID
        String certId1 = newCertHolder.getSerialNumber().toString();
        assertNotEquals(certId1, client.getCertificate().getSerialNumber().toString());
        // certificate failed to renew, client still hold the old expired cert.
        Thread.sleep(certificateLifetime * 1000);
        assertEquals(certId, client.getCertificate().getSerialNumber().toString());
        assertThrows(CertificateExpiredException.class, () -> client.getCertificate().checkValidity());
        assertThat(omLogs.getOutput()).contains("Error while signing and storing SCM signed certificate.");
        // provide a new valid SCMGetCertResponseProto
        newCertHolder = generateSelfSignedX509Cert(securityConfig, null, null, Duration.ofSeconds(certificateLifetime));
        pemCert = CertificateCodec.getPEMEncodedString(newCertHolder);
        responseProto = SCMSecurityProtocolProtos.SCMGetCertResponseProto.newBuilder().setResponseCode(SCMSecurityProtocolProtos.SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).setX509CACertificate(pemCert).build();
        when(scmClient.getOMCertChain(any(), anyString())).thenReturn(responseProto);
        String certId2 = newCertHolder.getSerialNumber().toString();
        // check after renew, client will have the new cert ID
        GenericTestUtils.waitFor(() -> {
            String newCertId = client.getCertificate().getSerialNumber().toString();
