@Test
public void testApplyTransactionExceptionAuditLog() throws Exception {
    ExitUtils.disableSystemExit();
    // submit a create volume request having null pointer exception
    OzoneManagerProtocolProtos.VolumeInfo volInfo = OzoneManagerProtocolProtos.VolumeInfo.newBuilder().setAdminName("a").setOwnerName("a").setVolume("a").build();
    OMRequest createVolRequest = OMRequest.newBuilder().setCreateVolumeRequest(OzoneManagerProtocolProtos.CreateVolumeRequest.newBuilder().setVolumeInfo(volInfo)).setCmdType(Type.CreateVolume).setClientId("123").setUserInfo(UserInfo.newBuilder().setUserName("user").setHostName("localhost").setRemoteAddress("127.0.0.1")).build();
    TransactionContext submittedTrx = mockTransactionContext(createVolRequest);
    Mockito.doAnswer((i) -> {
        if (!((AuditMessage) i.getArgument(0)).getFormattedMessage().contains("Transaction=10") || !((AuditMessage) i.getArgument(0)).getFormattedMessage().contains("Command=CreateVolume")) {
            Assertions.fail("transaction and command not found");
        }
        // throw another exception to change to new exception to avoid terminate call
        throw new OMException("test", OMException.ResultCodes.VOLUME_IS_REFERENCED);
    }).when(auditLogger).logWrite(any());
    CompletableFuture<Message> messageCompletableFuture = ozoneManagerStateMachine.applyTransaction(submittedTrx);
    try {
        messageCompletableFuture.get();
    } catch (Exception ex) {
        // do nothing
    }
}

