    S3SecretManager failingS3Secret = mock(S3SecretManager.class);
    doThrow(new IOException("Test Exception: Failed to store secret")).when(failingS3Secret).storeSecret(any(), any());
    when(failingS3Secret.doUnderLock(any(), any())).thenAnswer(invocationOnMock -> {
        S3SecretFunction<Boolean> action = invocationOnMock.getArgument(1, S3SecretFunction.class);
        return action.accept(failingS3Secret);
    });
    when(ozoneManager.getS3SecretManager()).thenReturn(failingS3Secret);
    assertThrows(Exception.class, () -> processSuccessSecretRequest(USER_ALICE, 1, true));
}

