@Test
public void testFetchSecretForRevokedUser() throws IOException {
    // Create a secret for "alice".
    // This effectively makes alice an S3 admin.
    when(ozoneManager.isS3Admin(ugiAlice)).thenReturn(true);
    String userPrincipalId = USER_ALICE;
    // Request the creation of a secret.
    S3Secret originalS3Secret = processSuccessSecretRequest(userPrincipalId, 1, true);
    // Revoke the secret.
    String kerberosID = originalS3Secret.getKerberosID();
    OzoneManagerProtocolProtos.RevokeS3SecretRequest revokeS3SecretRequest = OzoneManagerProtocolProtos.RevokeS3SecretRequest.newBuilder().setKerberosID(kerberosID).build();
    OMRequest revokeRequest = OMRequest.newBuilder().setRevokeS3SecretRequest(revokeS3SecretRequest).setClientId(UUID.randomUUID().toString()).setCmdType(Type.RevokeS3Secret).build();
    OMClientRequest omRevokeRequest = new S3RevokeSecretRequest(revokeRequest);
    // Pre-execute the revoke request.
    omRevokeRequest.preExecute(ozoneManager);
    // Validate and update cache to revoke the secret.
    OMClientResponse omRevokeResponse = omRevokeRequest.validateAndUpdateCache(ozoneManager, 2);
    // Verify that the revoke operation was successful.
    S3RevokeSecretResponse s3RevokeSecretResponse = assertInstanceOf(S3RevokeSecretResponse.class, omRevokeResponse);
    assertEquals(OzoneManagerProtocolProtos.Status.OK.getNumber(), s3RevokeSecretResponse.getOMResponse().getStatus().getNumber());
    // Fetch the revoked secret and verify its value is null.
    S3GetSecretRequest s3GetSecretRequest = new S3GetSecretRequest(new S3GetSecretRequest(s3GetSecretRequest(userPrincipalId)).preExecute(ozoneManager));
    S3SecretValue s3SecretValue = omMetadataManager.getSecret(kerberosID);
    assertNull(s3SecretValue);
    // Verify that the secret for revoked user will be set to a new one upon
    // calling getSecret request.
    OMClientResponse omClientResponse = s3GetSecretRequest.validateAndUpdateCache(ozoneManager, 3);
    assertInstanceOf(S3GetSecretResponse.class, omClientResponse);
    S3GetSecretResponse s3GetSecretResponse = (S3GetSecretResponse) omClientResponse;
    // Compare the old secret value and new secret value after revoking;
    // they should not be the same.
    assertNotEquals(originalS3Secret, s3GetSecretResponse.getS3SecretValue().getAwsSecret());
}

