@Test
public void testAddToDBBatch() throws Exception {
    final OzoneAcl user1 = OzoneAcl.of(USER, "user1", ACCESS, ACLType.READ_ACL);
    final OzoneAcl user2 = OzoneAcl.of(USER, "user2", ACCESS, ACLType.WRITE);
    final String prefixName = "/vol/buck/prefix/";
    List<OzoneAcl> acls = Arrays.asList(user1, user2);
    OmPrefixInfo omPrefixInfo = OmPrefixInfo.newBuilder().setName(prefixName).setAcls(acls).setUpdateID(1L).setObjectID(ThreadLocalRandom.current().nextLong()).build();
    OzoneManagerProtocolProtos.OMResponse setAclResponse = OzoneManagerProtocolProtos.OMResponse.newBuilder().setStatus(OzoneManagerProtocolProtos.Status.OK).setCmdType(OzoneManagerProtocolProtos.Type.SetAcl).setSetAclResponse(OzoneManagerProtocolProtos.SetAclResponse.newBuilder().setResponse(true).build()).build();
    OMPrefixAclResponse prefixAclResponse = new OMPrefixAclResponse(setAclResponse, omPrefixInfo);
    prefixAclResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Do manual commit and see whether addToBatch is successful or not.
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    OmPrefixInfo persistedPrefixInfo = omMetadataManager.getPrefixTable().getSkipCache(prefixName);
    assertEquals(omPrefixInfo, persistedPrefixInfo);
    String volumeName = "vol";
    String bucketName = "buck";
    OzoneManager ozoneManager = mock(OzoneManager.class);
    when(ozoneManager.resolveBucketLink(Pair.of(volumeName, bucketName))).thenReturn(new ResolvedBucket(volumeName, bucketName, volumeName, bucketName, "", BucketLayout.DEFAULT));
    // Verify that in-memory Prefix Tree (Radix Tree) is able to reload from
    // DB successfully
    PrefixManagerImpl prefixManager = new PrefixManagerImpl(ozoneManager, omMetadataManager, true);
    OzoneObj prefixObj = OzoneObjInfo.Builder.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setPrefixName("prefix/").setResType(OzoneObj.ResourceType.PREFIX).setStoreType(OzoneObj.StoreType.OZONE).build();
    OmPrefixInfo prefixInfo = prefixManager.getPrefixInfo(prefixObj);
    assertEquals(prefixName, prefixInfo.getName());
    assertEquals(1L, prefixInfo.getUpdateID());
    List<OzoneAcl> ozoneAcls = prefixManager.getAcl(prefixObj);
    assertEquals(2, ozoneAcls.size());
    assertEquals(acls, ozoneAcls);
    OzoneManagerProtocolProtos.OMResponse removeAclResponse = OzoneManagerProtocolProtos.OMResponse.newBuilder().setStatus(OzoneManagerProtocolProtos.Status.OK).setCmdType(OzoneManagerProtocolProtos.Type.RemoveAcl).setRemoveAclResponse(OzoneManagerProtocolProtos.RemoveAclResponse.newBuilder().setResponse(true).build()).build();
    // Remove user2 ACL
    OmPrefixInfo removeOnePrefixInfo = OmPrefixInfo.newBuilder().setName(prefixName).setAcls(Collections.singletonList(user1)).setUpdateID(2L).setObjectID(ThreadLocalRandom.current().nextLong()).build();
    prefixAclResponse = new OMPrefixAclResponse(removeAclResponse, removeOnePrefixInfo);
    prefixAclResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Do manual commit and see whether addToBatch is successful or not.
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    // Reload prefix tree from DB and validate again.
    prefixManager = new PrefixManagerImpl(ozoneManager, omMetadataManager, true);
    prefixInfo = prefixManager.getPrefixInfo(prefixObj);
    assertEquals(2L, prefixInfo.getUpdateID());
    ozoneAcls = prefixManager.getAcl(prefixObj);
    assertEquals(1, ozoneAcls.size());
    assertEquals(Collections.singletonList(user1), ozoneAcls);
    persistedPrefixInfo = omMetadataManager.getPrefixTable().getSkipCache(prefixName);
    assertEquals(removeOnePrefixInfo, persistedPrefixInfo);
    // Remove all ACL
    OmPrefixInfo removeAllPrefixInfo = OmPrefixInfo.newBuilder().setName(prefixName).setAcls(Collections.emptyList()).setUpdateID(3L).setObjectID(ThreadLocalRandom.current().nextLong()).build();
    prefixAclResponse = new OMPrefixAclResponse(removeAclResponse, removeAllPrefixInfo);
    prefixAclResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Do manual commit and see whether addToBatch is successful or not.
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    assertNull(omMetadataManager.getPrefixTable().getSkipCache(prefixName));
}

