    columnFamilyHandles = new ArrayList<>();
    db = ManagedRocksDB.open(dbOptions, dbDir.getAbsolutePath(), columnFamilyDescriptors, columnFamilyHandles);
    snapDiffJobTable = db.get().createColumnFamily(new ColumnFamilyDescriptor(StringUtils.string2Bytes(SNAP_DIFF_JOB_TABLE_NAME), columnFamilyOptions));
    snapDiffReportTable = db.get().createColumnFamily(new ColumnFamilyDescriptor(StringUtils.string2Bytes(SNAP_DIFF_REPORT_TABLE_NAME), columnFamilyOptions));
    columnFamilyHandles.add(snapDiffJobTable);
    columnFamilyHandles.add(snapDiffReportTable);
    String snapshotNamePrefix = "snap-";
    String snapshotPath = "snapshotPath";
    String snapshotCheckpointDir = "snapshotCheckpointDir";
