@ParameterizedTest(name = "{0}")
@MethodSource("threadPoolFullScenarios")
public void testThreadPoolIsFull(String description, long waitBetweenBatches, int expectInProgressJobsCount, int expectRejectedJobsCount) throws Exception {
    ExecutorService executorService = new ThreadPoolExecutor(100, 100, 0, TimeUnit.MILLISECONDS, new SynchronousQueue<>());
    List<SnapshotInfo> snapshotInfos = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        UUID snapshotId = UUID.randomUUID();
        String snapshotName = "snap-" + snapshotId;
        SnapshotInfo snapInfo = new SnapshotInfo.Builder().setSnapshotId(snapshotId).setVolumeName(VOLUME_NAME).setBucketName(BUCKET_NAME).setName(snapshotName).setSnapshotPath("fromSnapshotPath").setCheckpointDir("fromSnapshotCheckpointDir").build();
        snapshotInfos.add(snapInfo);
        when(snapshotInfoTable.get(getTableKey(VOLUME_NAME, BUCKET_NAME, snapshotName))).thenReturn(snapInfo);
    }
    SnapshotDiffManager spy = spy(snapshotDiffManager);
    for (int i = 0; i < snapshotInfos.size(); i++) {
        for (int j = i + 1; j < snapshotInfos.size(); j++) {
            String fromSnapshotName = snapshotInfos.get(i).getName();
            String toSnapshotName = snapshotInfos.get(j).getName();
            doAnswer(invocation -> {
                Thread.sleep(250L);
                return null;
            }).when(spy).generateSnapshotDiffReport(anyString(), anyString(), eq(VOLUME_NAME), eq(BUCKET_NAME), eq(fromSnapshotName), eq(toSnapshotName), eq(false), eq(false));
        }
    }
    List<Future<SnapshotDiffResponse>> futures = new ArrayList<>();
    for (int i = 0; i < snapshotInfos.size(); i++) {
        for (int j = i + 1; j < snapshotInfos.size(); j++) {
            String fromSnapshotName = snapshotInfos.get(i).getName();
            String toSnapshotName = snapshotInfos.get(j).getName();
            Future<SnapshotDiffResponse> future = executorService.submit(() -> submitJob(spy, fromSnapshotName, toSnapshotName));
            futures.add(future);
        }
        Thread.sleep(waitBetweenBatches);
    }
    // Wait to make sure that all jobs finish before assertion.
    Thread.sleep(1000L);
    int inProgressJobsCount = 0;
    int rejectedJobsCount = 0;
    for (Future<SnapshotDiffResponse> future : futures) {
        SnapshotDiffResponse response = future.get();
        if (response.getJobStatus() == IN_PROGRESS) {
            inProgressJobsCount++;
        } else if (response.getJobStatus() == REJECTED) {
            rejectedJobsCount++;
        } else {
            throw new IllegalStateException("Unexpected job status.");
        }
    }
    assertEquals(expectInProgressJobsCount, inProgressJobsCount);
    assertEquals(expectRejectedJobsCount, rejectedJobsCount);
    int notFoundJobs = 0;
    for (int i = 0; i < snapshotInfos.size(); i++) {
        for (int j = i + 1; j < snapshotInfos.size(); j++) {
            SnapshotDiffJob diffJob = getSnapshotDiffJobFromDb(snapshotInfos.get(i), snapshotInfos.get(j));
            if (diffJob == null) {
                notFoundJobs++;
            }
        }
    }
    // assert that rejected jobs were removed from the job table as well.
    assertEquals(expectRejectedJobsCount, notFoundJobs);
    executorService.shutdown();
}

