@BeforeEach
public void init() throws RocksDBException, IOException, ExecutionException {
    ExitUtils.disableSystemExit();
    ExitUtil.disableSystemExit();
    dbOptions = new ManagedDBOptions();
    dbOptions.setCreateIfMissing(true);
    columnFamilyOptions = new ManagedColumnFamilyOptions();
    List<ColumnFamilyDescriptor> columnFamilyDescriptors = Collections.singletonList(new ColumnFamilyDescriptor(StringUtils.string2Bytes(DEFAULT_COLUMN_FAMILY_NAME), columnFamilyOptions));
    columnFamilyHandles = new ArrayList<>();
    db = ManagedRocksDB.open(dbOptions, dbDir.getAbsolutePath(), columnFamilyDescriptors, columnFamilyHandles);
    snapDiffJobTable = db.get().createColumnFamily(new ColumnFamilyDescriptor(StringUtils.string2Bytes(SNAP_DIFF_JOB_TABLE_NAME), columnFamilyOptions));
    snapDiffReportTable = db.get().createColumnFamily(new ColumnFamilyDescriptor(StringUtils.string2Bytes(SNAP_DIFF_REPORT_TABLE_NAME), columnFamilyOptions));
    columnFamilyHandles.add(snapDiffJobTable);
    columnFamilyHandles.add(snapDiffReportTable);
    String snapshotNamePrefix = "snap-";
    String snapshotPath = "snapshotPath";
    String snapshotCheckpointDir = "snapshotCheckpointDir";
    UUID baseSnapshotId = UUID.randomUUID();
    String baseSnapshotName = snapshotNamePrefix + baseSnapshotId;
    snapshotInfo = new SnapshotInfo.Builder().setSnapshotId(baseSnapshotId).setVolumeName(VOLUME_NAME).setBucketName(BUCKET_NAME).setName(baseSnapshotName).setSnapshotPath(snapshotPath).setCheckpointDir(snapshotCheckpointDir).build();
    for (JobStatus jobStatus : jobStatuses) {
        UUID targetSnapshotId = UUID.randomUUID();
        String targetSnapshotName = snapshotNamePrefix + targetSnapshotId;
        SnapshotInfo targetSnapshot = new SnapshotInfo.Builder().setSnapshotId(targetSnapshotId).setVolumeName(VOLUME_NAME).setBucketName(BUCKET_NAME).setName(targetSnapshotName).setSnapshotPath(snapshotPath).setCheckpointDir(snapshotCheckpointDir).build();
        SnapshotDiffJob diffJob = new SnapshotDiffJob(System.currentTimeMillis(), UUID.randomUUID().toString(), jobStatus, VOLUME_NAME, BUCKET_NAME, baseSnapshotName, targetSnapshotName, false, false, 0, null, 0.0);
        snapshotNames.add(targetSnapshotName);
        snapshotInfoList.add(targetSnapshot);
        snapDiffJobs.add(diffJob);
    }
    String bucketTableKey = OM_KEY_PREFIX + VOLUME_NAME + OM_KEY_PREFIX + BUCKET_NAME;
