private void setupMocksForRunningASnapDiff(String volumeName, String bucketName) throws IOException {
    Map<BucketLayout, String> keyTableMap = new HashMap<>();
    keyTableMap.put(BucketLayout.FILE_SYSTEM_OPTIMIZED, FILE_TABLE);
    keyTableMap.put(BucketLayout.OBJECT_STORE, KEY_TABLE);
    keyTableMap.put(BucketLayout.LEGACY, KEY_TABLE);
    for (Map.Entry<BucketLayout, String> entry : keyTableMap.entrySet()) {
        when(omMetadataManager.getKeyTable(entry.getKey())).thenReturn(keyInfoTable);
        when(omMetadataManager.getKeyTable(entry.getKey()).getName()).thenReturn(entry.getValue());
    }
    UserGroupInformation ugi = UserGroupInformation.getCurrentUser();
    OmBucketInfo bucketInfo = OmBucketInfo.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setBucketLayout(BucketLayout.FILE_SYSTEM_OPTIMIZED).setOwner(ugi.getShortUserName()).build();
    String bucketKey = omMetadataManager.getBucketKey(volumeName, bucketName);
    when(bucketInfoTable.get(bucketKey)).thenReturn(bucketInfo);
}

