@ValueSource(ints = { 0, 1, 2, 5, 10, 100, 1000, 10000 })
public void testGetDeltaFilesWithDag(int numberOfFiles) throws IOException {
    UUID snap1 = UUID.randomUUID();
    UUID snap2 = UUID.randomUUID();
    when(snapshotInfoTable.get(SnapshotInfo.getTableKey(VOLUME_NAME, BUCKET_NAME, snap1.toString()))).thenReturn(getSnapshotInfoInstance(VOLUME_NAME, BUCKET_NAME, snap1.toString(), snap2));
    when(snapshotInfoTable.get(SnapshotInfo.getTableKey(VOLUME_NAME, BUCKET_NAME, snap2.toString()))).thenReturn(getSnapshotInfoInstance(VOLUME_NAME, BUCKET_NAME, snap2.toString(), snap2));
    String diffDir = snapDiffDir.getAbsolutePath();
    String diffJobKey = snap1 + DELIMITER + snap2;
    Set<String> randomStrings = IntStream.range(0, numberOfFiles).mapToObj(i -> RandomStringUtils.secure().nextAlphabetic(10)).collect(Collectors.toSet());
    when(differ.getSSTDiffListWithFullPath(any(DifferSnapshotInfo.class), any(DifferSnapshotInfo.class), eq(diffDir))).thenReturn(Optional.of(Lists.newArrayList(randomStrings)));
    UncheckedAutoCloseableSupplier<OmSnapshot> rcFromSnapshot = omSnapshotManager.getActiveSnapshot(VOLUME_NAME, BUCKET_NAME, snap1.toString());
    UncheckedAutoCloseableSupplier<OmSnapshot> rcToSnapshot = omSnapshotManager.getActiveSnapshot(VOLUME_NAME, BUCKET_NAME, snap2.toString());
    OmSnapshot fromSnapshot = rcFromSnapshot.get();
    OmSnapshot toSnapshot = rcToSnapshot.get();
    SnapshotInfo fromSnapshotInfo = getMockedSnapshotInfo(snap1);
    SnapshotInfo toSnapshotInfo = getMockedSnapshotInfo(snap2);
    when(jobTableIterator.isValid()).thenReturn(false);
    try (MockedStatic<RdbUtil> mockedRdbUtil = Mockito.mockStatic(RdbUtil.class, Mockito.CALLS_REAL_METHODS);
        MockedStatic<RocksDiffUtils> mockedRocksDiffUtils = Mockito.mockStatic(RocksDiffUtils.class, Mockito.CALLS_REAL_METHODS)) {
        mockedRdbUtil.when(() -> RdbUtil.getSSTFilesForComparison(any(), any())).thenReturn(Collections.singleton(RandomStringUtils.secure().nextAlphabetic(10)));
        mockedRocksDiffUtils.when(() -> RocksDiffUtils.filterRelevantSstFiles(any(), any())).thenAnswer(i -> null);
        SnapshotDiffManager spy = spy(snapshotDiffManager);
        doNothing().when(spy).recordActivity(any(), any());
