@Test
@SuppressWarnings({ "unchecked", "varargs" })
public void testGetKeyInfo() throws IOException {
    final DatanodeDetails dn1 = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dn2 = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dn3 = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dn4 = MockDatanodeDetails.randomDatanodeDetails();
    final long containerID = CONTAINER_ID.incrementAndGet();
    Set<Long> containerIDs = newHashSet(containerID);
    final Pipeline pipeline1 = Pipeline.newBuilder().setId(PipelineID.randomId()).setReplicationConfig(RatisReplicationConfig.getInstance(ReplicationFactor.THREE)).setState(Pipeline.PipelineState.OPEN).setLeaderId(dn1.getID()).setNodes(Arrays.asList(dn1, dn2, dn3)).build();
    final Pipeline pipeline2 = Pipeline.newBuilder().setId(PipelineID.randomId()).setReplicationConfig(RatisReplicationConfig.getInstance(ReplicationFactor.THREE)).setState(Pipeline.PipelineState.OPEN).setLeaderId(dn1.getID()).setNodes(Arrays.asList(dn2, dn3, dn4)).build();
    ContainerInfo ci = mock(ContainerInfo.class);
    when(ci.getContainerID()).thenReturn(1L);
    // Setup SCM containerClient so that 1st call returns pipeline1 and
    // 2nd call returns pipeline2.
    when(containerClient.getContainerWithPipelineBatch(containerIDs)).thenReturn(singletonList(new ContainerWithPipeline(ci, pipeline1)), singletonList(new ContainerWithPipeline(ci, pipeline2)));
    final String volume = volumeName();
    insertVolume(volume);
    insertBucket(volume, "bucketOne");
    BlockID blockID1 = new BlockID(containerID, 1L);
    insertKey(null, volume, "bucketOne", "keyOne", blockID1);
    BlockID blockID2 = new BlockID(containerID, 2L);
    insertKey(null, volume, "bucketOne", "keyTwo", blockID2);
    // 1st call to get key1.
    OmKeyArgs keyArgs = new Builder().setVolumeName(volume).setBucketName("bucketOne").setKeyName("keyOne").build();
    OmKeyInfo keyInfo = keyManager.getKeyInfo(keyArgs, resolveBucket(keyArgs), "test");
    final OmKeyLocationInfo blockLocation1 = keyInfo.getLatestVersionLocations().getBlocksLatestVersionOnly().get(0);
    assertEquals(blockID1, blockLocation1.getBlockID());
    assertEquals(pipeline1, blockLocation1.getPipeline());
    // Ensure SCM is called.
    verify(containerClient, times(1)).getContainerWithPipelineBatch(containerIDs);
    // subsequent call to key2 in same container sound result no scm calls.
    keyArgs = new Builder().setVolumeName(volume).setBucketName("bucketOne").setKeyName("keyTwo").build();
    OmKeyInfo keyInfo2 = keyManager.getKeyInfo(keyArgs, resolveBucket(keyArgs), "test");
    OmKeyLocationInfo blockLocation2 = keyInfo2.getLatestVersionLocations().getBlocksLatestVersionOnly().get(0);
    assertEquals(blockID2, blockLocation2.getBlockID());
    assertEquals(pipeline1, blockLocation2.getPipeline());
    // Ensure SCM is not called.
    verify(containerClient, times(1)).getContainerWithPipelineBatch(containerIDs);
    // Yet, another call with forceCacheUpdate should trigger a call to SCM.
    keyArgs = new Builder().setVolumeName(volume).setBucketName("bucketOne").setKeyName("keyTwo").setForceUpdateContainerCacheFromSCM(true).build();
    keyInfo2 = keyManager.getKeyInfo(keyArgs, resolveBucket(keyArgs), "test");
    blockLocation2 = keyInfo2.getLatestVersionLocations().getBlocksLatestVersionOnly().get(0);
    assertEquals(blockID2, blockLocation2.getBlockID());
    assertEquals(pipeline2, blockLocation2.getPipeline());
    // Ensure SCM is called.
    verify(containerClient, times(2)).getContainerWithPipelineBatch(containerIDs);
}

