@Test
public void testValidateAndUpdateCacheWhenVolumeExists() throws Exception {
    // Check that forceCreationWhenVolumeExists flag behaves as expected
    final String tenantId = UUID.randomUUID().toString();
    final String ownerName = "username";
    // Deliberately put volume entry in VolumeTable, to simulate the case where
    //  the volume already exists.
    OMRequestTestUtils.addVolumeToDB(tenantId, ownerName, omMetadataManager);
    // First with forceCreationWhenVolumeExists = false
    OMRequest originalRequest = OMRequestTestUtils.createTenantRequest(tenantId, false);
    OMTenantCreateRequest omTenantCreateRequest1 = spy(new OMTenantCreateRequest(originalRequest));
    doReturn(ownerName).when(omTenantCreateRequest1).getUserName();
    // Should throw in preExecute
    OMException omException = assertThrows(OMException.class, () -> omTenantCreateRequest1.preExecute(ozoneManager));
    assertEquals(VOLUME_ALREADY_EXISTS, omException.getResult());
    // Now with forceCreationWhenVolumeExists = true
    originalRequest = OMRequestTestUtils.createTenantRequest(tenantId, true);
    OMTenantCreateRequest omTenantCreateRequest2 = spy(new OMTenantCreateRequest(originalRequest));
    doReturn(ownerName).when(omTenantCreateRequest2).getUserName();
    // Should not throw now that forceCreationWhenVolumeExists = true
    OMRequest modifiedRequest = omTenantCreateRequest2.preExecute(ozoneManager);
    omTenantCreateRequest2 = new OMTenantCreateRequest(modifiedRequest);
    // Craft a request that sets forceCreationWhenVolumeExists to false to test
    //  validateAndUpdateCache.
    CreateTenantRequest reqPostPreExecute = omTenantCreateRequest2.getOmRequest().getCreateTenantRequest();
    OMRequest modReqPostPreExecute = omTenantCreateRequest2.getOmRequest().toBuilder().setCreateTenantRequest(CreateTenantRequest.newBuilder().setTenantId(tenantId).setVolumeName(reqPostPreExecute.getVolumeName()).setUserRoleName(reqPostPreExecute.getUserRoleName()).setAdminRoleName(reqPostPreExecute.getAdminRoleName()).setForceCreationWhenVolumeExists(false)).build();
    OMTenantCreateRequest modTenantCreateRequest = new OMTenantCreateRequest(modReqPostPreExecute);
    // OMResponse should have status VOLUME_ALREADY_EXISTS in this crafted case
    OMClientResponse modOMClientResponse = modTenantCreateRequest.validateAndUpdateCache(ozoneManager, 2L);
    assertEquals(Status.VOLUME_ALREADY_EXISTS, modOMClientResponse.getOMResponse().getStatus());
    assertEquals("Volume already exists", modOMClientResponse.getOMResponse().getMessage());
    // validateAndUpdateCache with forceCreationWhenVolumeExists = true
    OMClientResponse omClientResponse = omTenantCreateRequest2.validateAndUpdateCache(ozoneManager, 2L);
    OMResponse omResponse = omClientResponse.getOMResponse();
    assertNotNull(omResponse.getCreateTenantResponse());
    assertEquals(Status.OK, omResponse.getStatus());
    assertNotNull(omMetadataManager.getVolumeTable().get(omMetadataManager.getVolumeKey(tenantId)));
}

