@Test
public void testRejectNonS3CompliantTenantIdCreationWithStrictS3True() {
    String[] nonS3CompliantTenantId = { "tenantid_underscore", "_tenantid___multi_underscore_", "tenantid_" };
    when(ozoneManager.isStrictS3()).thenReturn(true);
    for (String tenantId : nonS3CompliantTenantId) {
        OMException omException = assertThrows(OMException.class, () -> doPreExecute(tenantId));
        assertEquals("Invalid volume name: " + tenantId, omException.getMessage());
    }
}

@Test
public void testAcceptNonS3CompliantTenantIdCreationWithStrictS3False() throws Exception {
    String[] nonS3CompliantTenantId = { "tenantid_underscore", "_tenantid___multi_underscore_", "tenantid_" };
    when(ozoneManager.isStrictS3()).thenReturn(false);
    for (String tenantId : nonS3CompliantTenantId) {
        acceptTenantIdCreationHelper(tenantId);
    }
}

private void doPreExecute(String tenantId) throws Exception {
    OMRequest originalRequest = OMRequestTestUtils.createTenantRequest(tenantId, false);
    OMTenantCreateRequest omTenantCreateRequest = spy(new OMTenantCreateRequest(originalRequest));
    doReturn("username").when(omTenantCreateRequest).getUserName();
    omTenantCreateRequest.preExecute(ozoneManager);
}

