    assertTrue(resultSet.stream().anyMatch(o -> o.getVolume().equals("vol1") && o.getBucket().equals("bucket1") && o.getFileSize() == 1024L && o.getCount() == 2L));
    assertTrue(resultSet.stream().anyMatch(o -> o.getVolume().equals("vol1") && o.getBucket().equals("bucket1") && o.getFileSize() == 131072 && o.getCount() == 2L));
    assertTrue(resultSet.stream().anyMatch(o -> o.getVolume().equals("vol2") && o.getBucket().equals("bucket1") && o.getFileSize() == 1024L && o.getCount() == 2L));
