public void testNegativeSizeRecordNotInsertedButLogged() {
    // Simulate a container with NEGATIVE_SIZE state
    // Negative size
    when(container.getUsedBytes()).thenReturn(-10L);
    Set<ContainerReplica> replicas = generateReplicas(container, CLOSED, CLOSED);
    ContainerHealthStatus status = new ContainerHealthStatus(container, replicas, placementPolicy, reconContainerMetadataManager, CONF);
    // Initialize stats map
    Map<UnHealthyContainerStates, Map<String, Long>> unhealthyContainerStateStatsMap = new HashMap<>();
    initializeUnhealthyContainerStateStatsMap(unhealthyContainerStateStatsMap);
    // Generate records for NEGATIVE_SIZE container
    List<UnhealthyContainers> records = ContainerHealthTask.ContainerHealthRecords.generateUnhealthyRecords(status, (long) 123456, unhealthyContainerStateStatsMap);
    // Assert that none of the records are for negative.
    records.forEach(record -> assertNotEquals(UnHealthyContainerStates.NEGATIVE_SIZE.toString(), record.getContainerState()));
    // Assert that the NEGATIVE_SIZE state is logged
    assertEquals(1, unhealthyContainerStateStatsMap.get(UnHealthyContainerStates.NEGATIVE_SIZE).getOrDefault(CONTAINER_COUNT, 0L));
}

