    ReconContainerSizeMetadataManager reconContainerSizeMetadataManager = mock(ReconContainerSizeMetadataManager.class);
    ReconTaskControllerImpl testController = new ReconTaskControllerImpl(ozoneConfiguration, new HashSet<>(), reconTaskStatusUpdaterManagerMock, reconDbProvider, reconContainerMgr, nsSummaryManager, reconGlobalStatsManager, reconFileMetadataManager, reconContainerSizeMetadataManager);
