@Test
public void testUpgradeAppliesConstraintModificationForAllStates() throws SQLException {
    // Run the upgrade action
    upgradeAction.execute(mockScmFacade.getDataSource());
    // Iterate over all valid states and insert records
    for (ContainerSchemaDefinition.UnHealthyContainerStates state : ContainerSchemaDefinition.UnHealthyContainerStates.values()) {
        dslContext.insertInto(DSL.table(UNHEALTHY_CONTAINERS_TABLE_NAME)).columns(field(name("container_id")), field(name("container_state")), field(name("in_state_since")), field(name("expected_replica_count")), field(name("actual_replica_count")), field(name("replica_delta")), field(name("reason"))).values(// Unique container_id for each record
        System.currentTimeMillis(), state.name(), System.currentTimeMillis(), 3, 2, 1, "Replica count mismatch").execute();
    }
    // Verify that the number of inserted records matches the number of enum values
    int count = dslContext.fetchCount(DSL.table(UNHEALTHY_CONTAINERS_TABLE_NAME));
    assertEquals(ContainerSchemaDefinition.UnHealthyContainerStates.values().length, count, "Expected one record for each valid state");
    // Try inserting an invalid state (should fail due to constraint)
    assertThrows(org.jooq.exception.DataAccessException.class, () -> dslContext.insertInto(DSL.table(UNHEALTHY_CONTAINERS_TABLE_NAME)).columns(field(name("container_id")), field(name("container_state")), field(name("in_state_since")), field(name("expected_replica_count")), field(name("actual_replica_count")), field(name("replica_delta")), field(name("reason"))).values(999L, "INVALID_STATE", System.currentTimeMillis(), 3, 2, 1, "Invalid state test").execute(), "Inserting an invalid container_state should fail due to the constraint");
}

