@Test
public void testCopyObject() throws Exception {
    String destBucket = "b2";
    String destKey = "key2";
    // Create bucket
    clientStub.getObjectStore().createS3Bucket(destBucket);
    // Test for Success of CopyObjectSuccess Metric
    long oriMetric = metrics.getCopyObjectSuccess();
    ByteArrayInputStream body = new ByteArrayInputStream(CONTENT.getBytes(UTF_8));
    keyEndpoint.put(bucketName, keyName, CONTENT.length(), 1, null, null, null, body);
    // Add copy header, and then call put
    when(headers.getHeaderString(COPY_SOURCE_HEADER)).thenReturn(bucketName + "/" + urlEncode(keyName));
    keyEndpoint.put(destBucket, destKey, CONTENT.length(), 1, null, null, null, body);
    long curMetric = metrics.getCopyObjectSuccess();
    assertEquals(1L, curMetric - oriMetric);
    // Test for Failure of CopyObjectFailure Metric
    oriMetric = metrics.getCopyObjectFailure();
    // source and dest same
    when(headers.getHeaderString(STORAGE_CLASS_HEADER)).thenReturn("");
    OS3Exception e = assertThrows(OS3Exception.class, () -> keyEndpoint.put(bucketName, keyName, CONTENT.length(), 1, null, null, null, body), "Test for CopyObjectMetric failed");
    assertThat(e.getErrorMessage()).contains("This copy request is illegal");
    curMetric = metrics.getCopyObjectFailure();
    assertEquals(1L, curMetric - oriMetric);
}

